// Üretilen dosya: tool/ozgun/uret.py. Sanat · Antik Çağ ve Orta Çağ görsel sanatları: Mezopotamya, Mısır, Yunan, Roma ve Bizans (kabartmalar, Dor-İyon-Korint düzenleri, mozaik, fresk, ikona) (orta).
const ozArt17Orta = <(String, String, List<String>, String)>[
  ('Mısır heykeltıraşlığından etkilenen erken dönem Yunan kuros heykellerini Mısır\'daki öncüllerinden ayıran en belirgin yapısal fark aşağıdakilerden hangisidir?', 'Sırt destek bloğunun kaldırılması ve figürün tamamen çıplak işlenmesi', ['Sol ayağın yerine sağ ayağın bir adım öne doğru uzatılmış olması', 'Başın gövdeye oranla her zaman gerçekçi kontrapost açıyla döndürülmesi', 'Mermer yerine yalnızca pişmiş toprak ve ahşap malzemenin tercih edilmesi'], 'Yunan heykeltıraşlar Mısır\'ın cephesel duruşunu alsa da taş destek levhasını kaldırarak heykeli boşlukta bağımsızlaştırmış ve figürü çıplak betimlemiştir.'),
  ('Atina Akropolisi\'nde bulunan ve omzunda kurbanlık bir buzağı taşıyan sakallı erkek figürünü betimleyen MÖ 560 civarına tarihli ünlü Arkaik heykel hangisidir?', 'Moskhoforos', ['Kroisos Kurosu', 'Peplos Kore', 'Diskobolos'], 'Omzunda buzağı taşıyan adak heykeli Yunanca "buzağı taşıyıcı" anlamına gelen Moskhoforos adıyla tanınır.'),
  ('Argoslu heykeltıraş Polymedes tarafından yapıldığı bilinen ve annelerinin arabasını tapınağa çeken iki güçlü kardeşi betimleyen Delphi Arkeoloji Müzesi\'ndeki Arkaik ikiz kuros grubu hangisidir?', 'Kleobis ve Biton', ['Harmodios ve Aristogeiton', 'Kastor ve Polluks', 'Menelaos ve Patroklos'], 'Delphi\'de bulunan Kleobis ve Biton heykelleri, Peloponnesos ekolünün ağır, kaslı ve bloksu Arkaik üslubunu temsil eder.'),
  ('Dor düzenindeki tapınakların friz kuşağında üç dikey yivli taş levhalar ile kabartmalı veya boyalı kareye yakın panolar ardışık olarak sıralanır; bu iki mimari öğenin adı sırasıyla nedir?', 'Triglif ve metop', ['Arşitrav ve korniş', 'Ekhinus ve abakus', 'Naos ve pronaos'], 'Dor frizinde ahşap kiriş uçlarını simgeleyen üç yivli bölümlere triglif, aralarındaki kabartmalı levhalara ise metop denir.'),
  ('İyon düzenindeki bir tapınağın friz kuşağını Dor düzenindeki frizden ayıran en temel görsel özellik aşağıdakilerden hangisidir?', 'Trigliflerle bölünmeden kesintisiz devam eden sürekli bir kabartma kuşağı olması', ['Hiçbir figüratif kabartma içermeyip yalnızca geometrik menderes motifleriyle kaplanması', 'Arşitravın altında sütun başlıklarının hemen arkasında gizli bir kuşak oluşturması', 'Yalnızca tapınağın doğu cephesinde yer alıp diğer üç cephede tamamen boş bırakılması'], 'İyon frizi metop ve triglif bölünmesi olmaksızın kesintisiz bir anlatımsal kabartma şeridi (zoforos) biçiminde döner.'),
  ('Bir arkeolog kazıda yirmi sığ yivli, kaidesiz bir sütun tamburu ile yanında ortasında kalkanlı savaşçı kabartması bulunan kare bir taş levha bulmuştur; bu tapınak hangi düzendedir?', 'Dor düzeni', ['İyon düzeni', 'Korint düzeni', 'Aiol düzeni'], 'Kaidesiz, 20 keskin/sığ yivli sütunlar ve kare metop levhaları Dor düzeninin kesin ayırt edici elemanlarıdır.'),
  ('Antik Yunan tapınaklarının ön ve arka cephelerinde çift eğimli çatının oluşturduğu üçgen biçimli mimari alana ne ad verilir?', 'Alınlık (Pediment)', ['Arşitrav (Epistylion)', 'Stylobat (Subasman)', 'Opisthodomos'], 'Tapınağın kısa kenarlarında korniş ile kırma çatı arasında kalan üçgen heykel alanına alınlık (pediment/tympanon) denir.'),
  ('Aegina Adası\'ndaki Aphaia Tapınağı\'nın batı ve doğu alınlıklarında yer alan Troya Savaşı sahneleri neden Arkaik ile Erken Klasik Dönem arasındaki geçişi belgelemek açısından eşsizdir?', 'Batı alınlığı Arkaik gülümsemeli katı üslupta iken daha geç yapılan doğu alınlığının doğal ve dramatik Sert Üslup\'ta işlenmesi', ['Batı alınlığında tamamen pişmiş toprak figürler kullanılırken doğu alınlığında içi boş döküm bronz heykellerin tercih edilmesi', 'Batı alınlığının İyonik kesintisiz friz düzeninde, doğu alınlığının ise Korint tipi bitkisel bezemeli panolar halinde yapılması', 'Batı alınlığında yalnızca tanrılar betimlenirken doğu alınlığında tarihte ilk kez sıradan köylülerin ve tüccarların yer alması'], 'MÖ 500-480 arasına tarihlenen iki alınlık arasındaki yaklaşık on-on beş yıllık fark, Arkaik kalıplardan Erken Klasik gerçekçiliğe geçişi aynı yapıda gösterir.'),
  ('İdeal insan vücudunun matematiksel oranlarını açıkladığı "Kanon" adlı kuramsal kitabını somutlaştırmak üzere "Doryphoros" (Mızrak Taşıyan Atlet) heykelini yapan Klasik Dönem ustası kimdir?', 'Polykleitos', ['Myron', 'Skopas', 'Lysippos'], 'Argoslu Polykleitos, başın tüm vücuda oranını 1/7 olarak belirlediği Kanon kuramını Doryphoros heykelinde kusursuz kontrapost ile uygulamıştır.'),
  ('Polykleitos\'un kontrapost sistemini (chiastic denge) uyguladığı Doryphoros heykelinde sağ bacak vücut ağırlığını taşıyorsa sol bacak ve kolların konumu nasıldır?', 'Sol bacak geride serbest bükülü, sol kol mızrağı taşımak üzere gergin, sağ kol ise yanda serbesttir', ['Sol bacak da sağ bacak gibi dik ve gergin, her iki kol ise göğüs hizasında çapraz kenetlenmiştir', 'Sol bacak bir adım önde ağırlığı paylaşır durumda, sağ kol yukarıda zafer çelengi tutar haldedir', 'Sol bacak dizden tamamen yerden kesilmiş, her iki kol ise arkada bel boşluğunda birleştirilmiştir'], 'Polykleitos\'un çapraz (khiastik) dengesinde taşıyıcı sağ bacağa gerilimli sol kol, serbest sol bacağa ise gevşemiş sağ kol karşılık gelir.'),
  ('Başının etrafına zafer bandı bağlayan bir atleti betimleyen ve Polykleitos\'un olgunluk dönemine ait ünlü heykeli aşağıdakilerden hangisidir?', 'Diadumenos', ['Apoksiomenos', 'Diskoforos', 'Herakles Farnese'], 'Yunanca "bant bağlayan" anlamına gelen Diadumenos (MÖ 430 civarı), Polykleitos\'un Doryphoros\'a göre daha yumuşak ve akıcı üslubunu yansıtır.'),
  ('Pheidias\'ın Parthenon içine yaptığı Athena Parthenos ve Olympia\'ya yaptığı Zeus heykellerinde ten kısımlarında fildişi, giysi ve saçlarda altın levhalar kullanılan tekniğe ne ad verilir?', 'Krizelefantin', ['Koroplastik', 'Enkaustik', 'Toreutik'], 'Ahşap bir iskelet üzerine fildişi (khrysos-elephas) ve altın kaplanarak yapılan anıtsal kült heykeli tekniğine krizelefantin denir.'),
  ('Parthenon alınlıklarındaki tanrıça heykellerinde (örneğin Üç Tanrıça grubu) Pheidias ve atölyesinin kumaş kıvrımlarını bedene yapışmış gibi ince ve akıcı işlediği üslup nasıl adlandırılır?', 'Islak elbise üslubu', ['Arkaik kıvrım üslubu', 'Geometrik blok üslubu', 'Helenistik rokoko üslubu'], 'Kumaşın altındaki anatomiyi tüm zarafetiyle belli eden sık ve akışkan kıvrım tekniğine sanat tarihinde "ıslak elbise üslubu" (wet drapery) denir.'),
  ('Parthenon gibi Klasik Yunan tapınaklarında sütun gövdelerinin ortasına doğru verilen hafif dışbükey şişkinlik (optik düzeltme) mimarlık tarihinde hangi terimle karşılanır?', 'Entasis', ['Stylobat', 'Akroter', 'Peristasis'], 'Uzaktan bakıldığında düz sütunların ortası içbükeymiş gibi algılanmasını önlemek ve canlılık katmak için gövdeye verilen hafif şişkinliğe entasis denir.'),
  ('Olympia\'daki Zeus Tapınağı\'nın doğu alınlığında Pelops ile Kral Oinomaos arasındaki ölümcül araba yarışı başlamadan önceki gergin sessizlik anında tam merkezde hangi tanrı ayakta durur?', 'Zeus', ['Apollon', 'Poseidon', 'Ares'], 'Doğu alınlığının merkezinde hakem olarak Zeus, batı alınlığındaki Lapith-Kentaur savaşının merkezinde ise Apollon yer alır.'),
  ('MÖ 7. yüzyılda Yakındoğu ve Mısır ticaretiyle Yunan seramiğine sfenks, grifon, aslan, siren ve lotus-palmet motiflerinin girdiği döneme ve öncü kent merkezine ne ad verilir?', 'Oryantalizan Dönem – Korint', ['Arkaik Dönem – Sparta', 'Miken Dönemi – Tirins', 'Klasik Dönem – Thebai'], 'Doğu etkili fantastik hayvan frizleri ve rozet dolgularıyla karakterize edilen MÖ 7. yüzyıl Oryantalizan üslubunun başat seramik merkezi Korint\'tir.'),
  ('Kırmızı figür tekniğinin siyah figür tekniğinin yerini hızla almasının sanatsal açıdan sağladığı en büyük üstünlük aşağıdakilerden hangisidir?', 'Fırça kullanımının sert kazıma çizgilerine kıyasla kas yapısını, perspektif kısaltmayı (rakursi) ve yüz ifadelerini çok daha akıcı vermesi', ['Fırınlama sıcaklığını yarı yarıya düşürerek vazoların kırılma riskini tamamen ortadan kaldırması', 'Tek bir vazo üzerinde yirmiden fazla parlak gökkuşağı renginin aynı anda kullanılmasına olanak tanıması', 'Kil hazırlama ve çömlekçi çarkında biçimlendirme aşamalarına duyulan ihtiyacı ortadan kaldırması'], 'İnce fırça ve seyreltilmiş kil astarı (rölyef çizgisi ve tonlama), sanatçılara insan anatomisini üç boyutlu hacim ve kıvraklıkla resmetme özgürlüğü vermiştir.'),
  ('Vatikan Müzesi\'nde korunan ve Troya Savaşı kahramanları Akhilleus ile Aias\'ı mola sırasında zar/dama oynarken betimleyen ünlü siyah figürlü amforanın ressamı kimdir?', 'Eksekias', ['Euphronios', 'Andokides', 'Kleitias'], 'Siyah figür üslubunun en büyük ustası kabul edilen Eksekias, Akhilleus ve Aias amforasında psikolojik gerilimi ve ince kazıma işçiliğini zirveye taşımıştır.'),
  ('Kırmızı figür tekniğinin "Öncüler" (Pioneers) grubunun baş temsilcisi olan ve yaralı Sarpedon\'un Uyku (Hypnos) ile Ölüm (Thanatos) tarafından taşınmasını krater üzerine resmeden usta kimdir?', 'Euphronios', ['Lydos', 'Amasis Ressamı', 'Sophilos'], 'MÖ 515 civarına tarihlenen Sarpedon Krateri\'nin ressamı Euphronios, anatomik kas detaylarını ve kanayan yaraları dramatik bir anıtsallıkla işlemiştir.'),
  ('Klasik Dönem\'de özellikle mezar sunusu olarak kullanılan ve beyaz kil astar üzerine mat renklerle hüzünlü veda sahnelerinin işlendiği dar boyunlu yağ şişesi formu hangisidir?', 'Beyaz zeminli Lekythos', ['Siyah figürlü Kyliks', 'Geometrik Krater', 'Oryantalizan Aryballos'], 'Tek kulplu, ince uzun yağ kabı olan lekythoslar, MÖ 5. yüzyılda beyaz zemin tekniğiyle boyanarak ölü kültü ve mezar ritüellerinde kullanılmıştır.'),
  ('Üç kulplu yapısı (taşımak için iki yatay yan kulp, suyu dökmek için bir dikey arka kulp) ile çeşmelerden su taşımaya özel tasarlanmış Yunan vazo formu hangisidir?', 'Hydria', ['Kantharos', 'Rhyton', 'Skyphos'], 'Adını Yunanca su (hydor) kelimesinden alan hydria, iki yatay kaldırma ve bir dikey dökme kulpuyla kolayca ayırt edilir.'),
  ('Praksiteles\'in "Hermes ve Çocuk Dionysos" ile "Apollon Sauroktonos" gibi heykellerinde figürün bir desteğe yaslanarak kalçasını yana doğru esnetmesiyle oluşan zarif kıvrıma ne ad verilir?', 'Praksiteles S kıvrımı', ['Arkaik dikey eksen', 'Polykleitos kare kanonu', 'Myron sarmal dönüşü'], 'Figürün ağırlığını yanındaki ağaç kütüğü veya sütuna yaslayarak gövdesine yumuşak, akıcı bir "S" formu vermesi Praksiteles üslubunun imzasıdır.'),
  ('MÖ 4. yüzyıl heykeltıraşlığında derin göz çukurları, aralık dudaklar ve yukarı bakan bakışlarla yoğun duygusal gerilimi (pathos) heykellere taşıyan usta kimdir?', 'Skopas', ['Polykleitos', 'Agorakritos', 'Kresilas'], 'Paroslu heykeltıraş ve mimar Skopas, Halikarnassos Mozolesi kabartmaları ve "Çılgın Maenad" heykeliyle Helenistik duygusallığın habercisi olmuştur.'),
  ('Polykleitos\'un 1/7\'lik kanonunu değiştirerek baş-vücut oranını 1/8 yapan, figürleri daha ince uzun kurgulayan ve Büyük İskender\'in saray heykeltıraşı olan sanatçı kimdir?', 'Lysippos', ['Pheidias', 'Alkamenes', 'Paionios'], 'Sikyonlu Lysippos, "Apoksiomenos" (Kazınan Atlet) heykeliyle kolları öne uzatarak heykeli tek cepheden kurtarmış ve 1/8\'lik yeni oran sistemini getirmiştir.'),
  ('Bergama (Pergamon) Kralı I. Attalos\'un Galatlara karşı kazandığı zaferi anmak için dikilen ve düşmana bile saygı duyan trajik asalet anlayışını yansıtan ünlü heykel hangisidir?', 'Ölen Galyalı', ['Diskobolos', 'Doryphoros', 'Kritios Çocuğu'], 'Boynundaki tork kolyesi, dağınık saçları ve yaralı böğrüyle yere yığılan "Ölen Galyalı" (ve "Kendini ve Karısını Öldüren Galyalı"), Bergama ekolünün başyapıtıdır.'),
  ('Kaidesini çevreleyen yüksek kabartmalı dev frizinde Olympos tanrıları ile toprak ana Gaia\'nın oğulları devler arasındaki savaşı (Gigantomakhia) anlatan anıtsal Helenistik yapı hangisidir?', 'Bergama Zeus Sunağı', ['Efes Artemis Tapınağı', 'Halikarnassos Mozolesi', 'Didyma Apollon Tapınağı'], 'MÖ 2. yüzyılda II. Eumenes döneminde inşa edilen Bergama Sunağı, basamaklara taşan yüksek kabartmalarıyla "Helenistik Barok" üslubunun simgesidir.'),
  ('Kucağında şarap testisi tutan dişsiz, kırışık yüzlü, zayıf ve çökük bir ihtiyar kadını acımasız bir gerçekçilikle betimleyen Helenistik "janr" (günlük yaşam) heykeli hangisidir?', 'Sarhoş Yaşlı Kadın', ['Tanagra Figürini', 'Dinlenen Boksör', 'Diken Çıkaran Çocuk'], 'Münih ve Roma\'da kopyaları bulunan "Sarhoş Yaşlı Kadın" heykeli, Helenistik sanatın güzellik idealinin dışındaki düşkün ve yaşlı bedenlere duyduğu ilgiyi kanıtlar.'),
  ('Roma Ulusal Müzesi\'nde korunan, kırık burnu, şişmiş kulakları, yüzündeki bakır kakmalı kan damlalarıyla dövüş sonrası yorgunluğunu yansıtan Helenistik bronz heykel hangisidir?', 'Dinlenen Boksör', ['Delphi Arabacısı', 'Artemision Bronzu', 'Riace Savaşçıları'], 'Oturur vaziyette başını hızla yana çeviren "Dinlenen Boksör", bakır kakma yaraları ve bitkin anatomisiyle Helenistik gerçekçiliğin en çarpıcı orijinal bronzlarındandır.'),
  ('MÖ 478-474 yıllarında yapılan, uzun plili khiton giysisi ve sakin yüz ifadesiyle Erken Klasik Dönem\'den günümüze ulaşan en ünlü orijinal Yunan bronz heykellerinden biri hangisidir?', 'Delphi Arabacısı', ['Moskhoforos', 'Kroisos Kurosu', 'Laokoon Grubu'], 'Savaştan değil, Pythia araba yarışından zaferle çıkan takımı anmak için adanan Delphi Arabacısı, içi boş balmumu döküm tekniğinin ve Sert Üslup\'un şaheseridir.'),
  ('Güney İtalya\'nın Calabria kıyılarında deniz tabanından çıkarılan ve MÖ 5. yüzyıl Klasik Yunan orijinal bronz işçiliğini gümüş dişler, bakır dudaklar ve kakma gözlerle günümüze taşıyan iki heykel hangisidir?', 'Riace Bronzları', ['Kleobis ve Biton', 'Tiran Katilleri', 'Aegina Savaşçıları'], '1972\'de denizden çıkarılan Riace A ve B savaşçıları, kontrapost duruşları ve çok renkli metal kakma detaylarıyla Yüksek Klasik bronz sanatının en nadide özgün örnekleridir.'),
  ('Eğriboz Adası yakınlarındaki Artemision Burnu açıklarında batık bir gemiden çıkarılan, kollarını iki yana açmış yıldırım ya da üç dişli yaba fırlatmaya hazırlanan MÖ 460 tarihli dev bronz heykel kimi betimler?', 'Zeus veya Poseidon', ['Apollon veya Dionysos', 'Hermes veya Hephaistos', 'Ares veya Herakles'], 'Atina Ulusal Arkeoloji Müzesi\'ndeki Artemision Bronzu\'nun elindeki silah kayıp olduğu için fırlattığı nesneye göre Zeus (yıldırım) ya da Poseidon (trident) olarak tanımlanır.'),
  ('Antik Yunan mimarisinde ön ve arka cepheler dahil dört tarafı tek sıra sütun dizisiyle (peristasis) çevrili olan standart tapınak plan tipine ne ad verilir?', 'Peripteros', ['Dipteros', 'Prostylos', 'Antalı tapınak'], 'Naos (cella) odasını dört yönden tek sıra sütun galerisinin kuşattığı tapınak planına peripteros, çift sıra sütun kuşatırsa dipteros denir.'),
  ('Delphi ve Epidauros gibi kutsal alanlarda inşa edilen, dairesel planlı ve çevresi sütunlarla kuşatılmış Antik Yunan yapı tipine ne ad verilir?', 'Tholos', ['Stoa', 'Bouleuterion', 'Gymnasion'], 'Dairesel planlı peripteral yapılara Yunan mimarisinde Tholos adı verilir; Delphi Athena Pronaia Kutsal Alanı ve Epidauros\'taki örnekleri ünlüdür.'),
  ('Paeonios tarafından MÖ 421 civarında Olympia\'da yüksek üçgen bir kaide üzerine dikilen, rüzgarla geriye yapışan elbisesiyle gökten süzülüyormuş izlenimi veren zafer tanrıçası heykeli hangisidir?', 'Paeonios Nike\'si', ['Semadirek Nike\'si', 'Delos Arkhermos Nike\'si', 'Epidauros Nike\'si'], 'Olympia Müzesi\'ndeki Paeonios imzalı Nike heykeli, kartal üzerinde gökyüzünden iniş anını ıslak elbise üslubuyla yakalayan Yüksek Klasik Dönem eseridir.'),
  ('Sisam (Samos) Adası\'ndaki Hera Tapınağı\'na Cheramyes tarafından adanan, silindirik bir sütun gövdesini andıran sık plili giysisiyle İyon Arkaik ekolünü temsil eden başsız kore heykeli hangisidir?', 'Samos Heralı Kore', ['Auxerre Kadını', 'Phrasikleia Koresi', 'Antenor Koresi'], 'Louvre Müzesi\'ndeki Samos Koresi (Hera of Samos), ince keten khiton kıvrımları ve sütunsu silindirik formuyla MÖ 570-560 Doğu Yunan (İyon) Arkaik heykelinin simgesidir.'),
  ('Attika\'da Merenda\'da mezar işareti olarak dikilen, kırmızı boya izlerini ve lotus tacıyla Arkaik zarafetini koruyan, Aristion imzalı ünlü genç kız heykeli hangisidir?', 'Phrasikleia Koresi', ['Peplos Kore', 'Nikandre Koresi', 'Berlin Tanrıçası'], 'Kaidesindeki yazıtta evlenmeden genç yaşta öldüğü için sonsuza dek "kore" (genç kız) olarak anılacağı yazan Phrasikleia, MÖ 550-540 Arkaik polikromisinin en iyi korunmuş örneğidir.'),
  ('MÖ 600 civarına tarihlenen New York (Metropolitan) Kurosu ile MÖ 530 civarına tarihlenen Anavyssos (Kroisos) Kurosu karşılaştırıldığında Arkaik Dönem içindeki anatomik evrim nasıl özetlenir?', 'Keskin çizgisel ve bloksu geometrik anatomiden dolgun, yuvarlak kaslı ve doğal vücut geçişlerine doğru ilerlemiştir', ['Doğal ve hareketli kontrapost duruştan giderek tamamen soyut ve hareketsiz dikdörtgen sütun formuna dönüşmüştür', 'Tamamen giyimli ve sakallı yaşlı erkek tipinden çocuksu ve kanatlı mitolojik figür tipine doğru evrilmiştir', 'Baş-gövde oranı 1/9 gibi çok ince uzun bir yapıdan 1/4 gibi tıknaz ve cüce oranlara doğru kısalmıştır'], 'Yಪ್ಪmiş yıllık süreçte karın ve dizdeki çizgisel kazımalar yerini Kroisos Kurosu\'nda gerçekçi et-kas hacmine bırakmıştır.'),
  ('Atina Akropolisi\'nde bulunan, başını hafifçe sağa çevirmiş sakallı bir atlıyı betimleyen ve başı Louvre\'da, gövdesi Atina\'da korunan MÖ 550 tarihli ünlü Arkaik heykel hangisidir?', 'Rampin Süvarisi', ['Delphi Arabacısı', 'Moskhoforos', 'İskender Lahdi'], 'Mermerden yontulmuş en erken atlı heykel örneklerinden biri olan Rampin Süvarisi, ince işlenmiş saç-sakal bukleleri ve hafif baş dönüşüyle Arkaik frontaliteyi esnetir.'),
  ('Yunan tapınaklarının üç basamaklı taş alt yapısına genel olarak "krepis" (krepidoma) denir; sütunların doğrudan üzerine bastığı en üst basamağın özel adı nedir?', 'Stylobat', ['Stereobat', 'Arşitrav', 'Geison'], 'Alt basamaklara stereobat, sütunları (stylos) taşıyan en üst düzleme ise stylobat adı verilir.'),
  ('Tapınaklarda sütun başlıklarının hemen üzerine oturan ve çatı ağırlığını sütunlara aktaran yatay ana taş kiriş kuşağına ne ad verilir?', 'Arşitrav', ['Triglif', 'Akroter', 'Sima'], 'Üst yapının (entablatür) en alt elemanı olan ve sütunları birbirine bağlayan ana taşıyıcı kirişe arşitrav veya epistylion denir.'),
  ('Tapınak alınlığının tepe noktasına ve iki yan köşesine yerleştirilen palmet, sfenks, grifon veya Nike biçimli çatı süsleme heykellerine ne ad verilir?', 'Akroter', ['Antefiks', 'Metop', 'Mutulus'], 'Alınlığın üç köşesini taçlandıran kaideli plastik bezemelere akroter, çatı kiremitlerinin saçak ucunu kapatan süslü levhalara ise antefiks denir.'),
  ('Bir kazıda bulunan sütun gövdesinde keskin sırtlarla değil, düz şeritlerle (faturalarla) birbirinden ayrılmış 24 derin yiv saptanmıştır; bu sütun hangi düzen ailesine aittir?', 'İyon veya Korint düzeni', ['Erken Arkaik Dor düzeni', 'Klasik Dor düzeni', 'Miken saray düzeni'], 'Dor sütunlarında genellikle keskin sırtla birleşen 20 sığ yiv bulunurken, İyon ve Korint sütunlarında aralarında düz şerit (listel) bırakılan 24 derin yiv yer alır.'),
  ('Atina Agorası\'na yukarıdan bakan tepede yer alan ve Dor düzeninde günümüze çatısına kadar en sağlam ulaşmış Klasik Yunan tapınağı (MÖ 449 civarı) hangisidir?', 'Hephaistos Tapınağı', ['Olympeion Tapınağı', 'Sounion Poseidon Tapınağı', 'Bassae Apollon Tapınağı'], 'Metoplarında Herakles ve Theseus\'un kahramanlıkları işlendiği için halk arasında Theseion da denilen Hephaistos Tapınağı, en iyi korunmuş Dor tapınağıdır.'),
  ('Didyma\'daki (Didim) devasa Helenistik Apollon Tapınağı\'nın naos kısmını klasik Yunan tapınaklarından ayıran en özgün mimari özellik nedir?', 'Üstünün çatıyla örtülmeyip açık avlu (hypaethral) olarak bırakılması ve içinde küçük bir tapınakçık (naiskos) bulunması', ['Tamamen ahşap sütunlardan yapılıp her beş yılda bir yeniden sökülüp kurulması', 'Dairesel tholos planında inşa edilip ortasında döner bir kubbe taşıması', 'Hiçbir basamak ve sütun kullanılmadan kayaya oyulmuş yeraltı mağarası olması'], 'Didymaion çok devasa ölçekte olduğu için iç avlusu (adyton) üstü açık (hypaethral) tasarlanmış, kutsal kaynak ve kehanet tapınakçığı bu avlunun içine yerleştirilmiştir.'),
  ('Bodrum\'da Karia Satrabı Mausolos için MÖ 4. yüzyıl ortasında Pytheos tarafından tasarlanan ve Skopas, Bryaksis, Leokhares, Timotheos gibi dört ünlü heykeltıraşın çalıştığı anıt mezar hangisidir?', 'Halikarnassos Mozolesi', ['İskender Lahdi', 'Ağlayan Kadınlar Lahdi', 'Nereidler Anıtı'], 'Yüksek podyum, İyon sütunlu galeri ve basamaklı piramit çatıyı birleştiren Halikarnassos Mozolesi, kendisinden sonraki tüm anıtsal mezarlara "mozole" adını vermiştir.'),
  ('Her dört yılda bir Atina\'da düzenlenen Panathenaia Şenlikleri\'nde yarışma galiplerine kutsal zeytinyağı dolu olarak verilen amforalarda neden Klasik ve Helenistik dönemlerde bile siyah figür tekniği sürdürülmüştür?', 'Dini gelenek ve törensel muhafazakarlık gereği arkaik formun korunması istendiği için', ['Kırmızı figür tekniğindeki kil astarının zeytinyağı ile temas ettiğinde zehirli gaz çıkardığı için', 'Atinalı çömlekçilerin MÖ 400\'den sonra fırça kullanmayı tamamen unutmuş olmaları yüzünden', 'Siyah figürlü kapların kırmızı figürlü kaplara göre on kat daha hafif ve kırılmaz olmasından'], 'Kırmızı figür MÖ 530\'da icat edilmesine rağmen Panathenaia ödül amforalarında bir yüzünde mızraklı Athena, diğer yüzünde ilgili spor dalı olmak üzere siyah figür geleneği yüzyıllarca korunmuştur.'),
  ('Eksekias\'ın Münih\'te korunan ünlü siyah figürlü kyliksinin iç yüzeyinde (tondo) mercan kırmızısı zemin üzerinde asma dalları bitmiş yelkenli teknesiyle denizde süzülen tanrı kimdir?', 'Dionysos', ['Poseidon', 'Apollon', 'Hermes'], 'Kendisini kaçıran korsanları yunusa dönüştüren şarap tanrısı Dionysos\'un teknesini betimleyen bu kyliks, siyah figür kompozisyon sanatının zirvelerinden biridir.'),
  ('Büyük İskender\'in doğu seferi öncesinde saray ressamı olarak ün kazanan, ışık-gölge geçişlerindeki ustalığı ve "Denizden Çıkan Afrodit" (Aphrodite Anadyomene) tablosuyla antik çağın en büyük ressamı kabul edilen usta kimdir?', 'Apelles', ['Zeuksis', 'Parrhasios', 'Agatharkhos'], 'Koslu/Kolophonlu Apelles, Büyük İskender\'in portresini yapmasına izin verdiği tek ressam olup ince vernik (atramentum) ve zarif konturlarıyla efsaneleşmiştir.'),
  ('Pompeii\'deki Faun Evi\'nde bulunan, Büyük İskender ile Pers Kralı III. Dareios\'u İssos veya Gaugamela Savaşı\'nda karşı karşıya gösteren ünlü Roma taban mozaiği hangi dönem Yunan resminin kopyasıdır?', 'Erken Helenistik / Geç Klasik Dönem (Philoksenos tablosu)', ['Geometrik Dönem (Dipylon atölyesi)', 'Erken Arkaik Dönem (Korint ekolü)', 'Miken Dönemi (Tiryns saray freskleri)'], 'MÖ 4. yüzyıl sonlarında Eretrialı Philoksenos tarafından yapıldığı düşünülen kayıp bir Yunan tablosunun dört renkli (tetrakromatik) kusursuz mozaik kopyasıdır.'),
  ('Makedonya Krallığı\'nın eski başkenti Pella\'da bulunan, çakıl taşlarıyla (pebble mosaic) yapılmış "Geyik Avı" ve "Aslan Avı" mozaiklerinde gölgelendirme ve kas hacmi nasıl elde edilmiştir?', 'Farklı tonlardaki doğal dere çakılları ve dış hatları belirginleştiren ince kurşun-pişmiş toprak şeritler kullanılarak', ['Renkli cam küplerin üzerine altın yaprak eritilip duvar yüzeyine yapıştırılmasıyla', 'Tek renkli beyaz mermer zeminin fırçayla suluboya gibi boyanıp cilalanmasıyla', 'Siyah bazalt blokların içine fildişi ve mercan parçalarının kakılmasıyla'], 'MÖ 4. yüzyıl sonuna ait Pella mozaikleri (Gnosis imzalı Geyik Avı), kesme taş tessera öncesi doğal çakıl mozaik sanatının zirvesidir.'),
  ('Sayda (Sidon) Kraliyet Nekropolü\'nde Osman Hamdi Bey tarafından keşfedilen ve İstanbul Arkeoloji Müzeleri\'nde sergilenen, üzerinde Yunan-Pers av ve savaş sahneleri bulunan çok renkli mermer lahit hangisidir?', 'İskender Lahdi', ['Likya Lahdi', 'Satrap Lahdi', 'Tabnit Lahdi'], 'MÖ 4. yüzyıl sonuna tarihlenen İskender Lahdi, Sayda Kralı Abdalonymos\'a ait olup mermer üzerindeki polikrom boya kalıntılarını koruyan eşsiz bir Geç Klasik/Erken Helenistik şaheserdir.'),
  ('Yunanistan\'ın Boiotia bölgesindeki mezarlardan yoğun olarak çıkarılan, şapkalı, pelerinli zarif kadınları günlük giysileri içinde betimleyen kalıpla üretilmiş çok renkli pişmiş toprak heykelciklere ne ad verilir?', 'Tanagra figürinleri', ['Kiklad idolleri', 'Kuros heykelleri', 'Boiotia çan idolleri'], 'MÖ 4. ve 3. yüzyıllarda yaygınlaşan Tanagra heykelcikleri, Helenistik burjuva kadınlarının günlük zarafetini ve modasını yansıtan koroplastik ürünlerdir.'),
  ('Atina\'daki Kerameikos Mezarlığı\'nda bulunan "Hegeso\'nun Mezar Steli" (MÖ 410 civarı) Yüksek Klasik Dönem\'in ölüm ve yas anlayışını nasıl yansıtır?', 'Aşırı ağlama ve çırpınma yerine hizmetçisinin uzattığı mücevher kutusuna bakan kadının sessiz, ağırbaşlı hüznüyle', ['Ölen kişinin yeraltı canavarları tarafından parçalanışını gösteren korkutucu ve kanlı kabartmalarla', 'Mezar taşının üzerinde kahkahalar atan şölen davetlilerinin ve dansözlerin neşeli tasvirleriyle', 'İnsan figürüne yer vermeksizin yalnızca geometrik zikzaklar ve savaş arabası tekerlekleriyle'], 'Klasik Atina mezar stellerinde (örneğin Hegeso Steli) ölüm, yaşayanlarla ölen arasındaki sakin, vakur ve içe dönük bir veda anı (ethos) olarak betimlenir.'),
  ('Antik Yunan kadın ve erkek giyiminde heykellerde sıkça karşılaşılan, içe giyilen ince keten gömlek ile üzerine omuzdan sarılan dikdörtgen manto ikilisinin adları sırasıyla nedir?', 'Khiton ve Himatyon', ['Toga ve Tunika', 'Kalathos ve Polos', 'Petasos ve Khlamys'], 'Yunan heykelinde kıvrım etütlerinin temelini oluşturan ince iç giysiye khiton (kadınlarda yünlü olanına peplos), dışa sarılan pelerin/mantoya ise himatyon denir.'),
  ('Epidauros\'taki Asklepios Kutsal Alanı\'nda MÖ 4. yüzyılda Genç Polykleitos tarafından yamaca inşa edilen, kusursuz akustiği ve simetrik taş oturma sıralarıyla (koilon) ünlü yapı hangisidir?', 'Epidauros Tiyatrosu', ['Dionysos Tiyatrosu', 'Bergama Tiyatrosu', 'Herodes Attikos Odeionu'], 'Yaklaşık 14.000 kişilik Epidauros Tiyatrosu, dairesel orkestrası ve altın orana yakın oturma basamaklarıyla Antik Yunan tiyatro mimarisinin en yetkin örneğidir.'),
  ('Anadolu\'daki Bergama (Pergamon) Akropolisi\'nde yer alan Helenistik tiyatroyu Klasik Yunan tiyatrolarından ayıran en çarpıcı topografik özellik nedir?', 'Çok dik bir yamaç üzerine dar ve yüksek basamaklarla inşa edilerek ovaya hakim dramatik bir manzara kurması', ['Tamamen düz bir ova ortasına kemerli taş tonozlar üzerinde üç katlı kapalı bina olarak yapılması', 'İzleyici basamaklarının yarım daire yerine kare bir avlu etrafında dört yönden dizilmesi', 'Orkestra bölümünün suyla doldurularak yalnızca deniz savaşı gösterileri için kullanılması'], 'Bergama Akropolisi\'nin sarp yamacına tutunan 10.000 kişilik tiyatro, antik dünyanın en dik tiyatrosudur ve Helenistik Dönem\'in doğayla bütünleşen tiyatral şehirciliğini yansıtır.'),
  ('MÖ 5. yüzyılda kendi kenti Miletos\'un yeniden inşasında ve Pire Limanı\'nda birbirini dik kesen caddelerle oluşturulan ızgara kent planını sistemleştiren mimar ve kent plancısı kimdir?', 'Miletoslu Hippodamos', ['İktinos', 'Kallikrates', 'Vitruvius'], 'Dik açılı sokak adaları ve işlevsel bölgelere ayrılmış kent kurgusu, Miletoslu Hippodamos\'un adıyla "Hippodamik (ızgara) plan" olarak anılır.'),
  ('Pheidias\'ın öğrencisi Alkamenes\'in ya da bizzat Pheidias\'ın elinden çıktığı düşünülen, Parthenon\'un doğu alınlığında şarap tanrısı Dionysos (veya Herakles) olarak tanımlanan kaslı, uzanmış çıplak erkek heykelinin önemi nedir?', 'Alınlığın daralan sol köşesine doğal biçimde uzanırken Yüksek Klasik Dönem\'in idealize edilmiş sakin ve tanrısal anatomisini göstermesi', ['Yunan sanatında yüzünde acı içinde çığlık atan ilk yaşlı ve sakat savaşçı figürü olması', 'Tamamen mavi cam hamurundan dökülmüş tek büyük boyutlu tapınak alınlığı heykeli olması', 'Mısır firavun heykelleri gibi sırtı düz bir sütuna yapışık ve dimdik ayakta durması'], 'British Museum\'da bulunan bu heykel, doğan Güneş\'in (Helios) atlarına doğru rahatça uzanan görkemli anatomisiyle Pheidias üslubunun başyapıtıdır.'),
  ('Parthenon Tapınağı\'nın dış cephesindeki 92 Dor metopunda betimlenen dört büyük mitolojik savaş (Gigantomakhia, Amazonomakhia, Troya Savaşı ve Kentauromakhia) tarihsel-sembolik olarak neyi yüceltir?', 'Yunan uygarlığının ve düzeninin (kosmos) Pers istilasıyla özdeşleştirilen barbarlığa ve kaosa karşı zaferini', ['Atina kentinin Sparta ile kurduğu kalıcı barış antlaşmasını ve olimpiyat kardeşliğini', 'İnsanların doğa tanrılarına boyun eğerek deniz ticaretinden ve savaştan tamamen vazgeçmesini', 'Makedonya Kralı Büyük İskender\'in Mısır ve Hindistan topraklarını tek imparatorlukta birleştirmesini'], 'MÖ 480 Pers yıkımından sonra inşa edilen Parthenon\'da tanrıların devleri, Lapithlerin Kentaurları yenmesi, Yunanlıların Perslere karşı kazandığı uygarlık zaferinin metaforudur.'),
  ('Parthenon frizinde peş peşe dörtnala giden onlarca süvarinin 5 santimetreyi aşmayan sığ bir mermer derinliği içinde üst üste binmiş katmanlar halinde hacimli görünmesi hangi kabartma ustalığıyla sağlanmıştır?', 'Alçak kabartma (bas-relief) düzlemlerini kademeli açılarla kavisli yontarak gölge çizgileri oluşturmak', ['Atların başlarını ayrı bronz parçalar halinde döküp duvardan bir metre dışarıya doğru çivilemek', 'Arka sıradaki atları ön sıradakilerin yarısı kadar küçük çizerek çizgisel kaçış noktası kurmak', 'Mermer yüzeyi tamamen düz bırakıp derinliği yalnızca siyah ve beyaz boyayla taklit etmek'], 'Pheidias ve ustaları yalnızca birkaç santimetrelik sığ mermer kalınlığında 6-7 katmanlı at bacağı ve gövde geçişini milimetrik yüzey açılarıyla (alçak kabartma) çözmüştür.'),
  ('Klasik Dönem Atinalı devlet adamı Perikles\'i başında geriye itilmiş Korint miğferiyle idealize ederek betimleyen ve Plinius\'un "soylu insanları daha da soylu gösterdi" diye övdüğü heykeltıraş kimdir?', 'Kresilas', ['Myron', 'Skopas', 'Kallimakhos'], 'Giritli Kresilas\'ın MÖ 430 civarında yaptığı Perikles büstü, bireysel kusurları (uzun kafatasını miğferle) gizleyip demokratik liderlik idealini ön plana çıkaran Klasik portre anlayışını temsil eder.'),
  ('Ayak tabanına batan dikeni çıkarmak için bacak bacak üstüne atıp tüm dikkatiyle ayağına eğilmiş çıplak bir oğlan çocuğunu betimleyen ünlü Helenistik heykel hangisidir?', 'Spinario', ['Kazla Boğuşan Çocuk', 'Kritios Çocuğu', 'Eros ve Psykhe'], 'Roma Capitolini Müzesi\'ndeki "Spinario", günlük ve sıradan bir anı samimi bir doğallıkla yakalayan Helenistik janr heykelinin en sevilen örneklerindendir.'),
  ('Helenistik "Rokoko" eğiliminin en sevimli örneklerinden olan, Khalkedonlu Boethos\'un eseri olup kendisi kadar büyük bir kuşun boynuna sarılmış tombul bir bebeği betimleyen heykel hangisidir?', 'Kazla Boğuşan Çocuk', ['Moskhoforos', 'Apollon Sauroktonos', 'Diadumenos'], 'Çocuk anatomisinin yumuşak tombulluğunu ve mizahi direncini ustalıkla veren Boethos\'un "Kazla Boğuşan Çocuk" grubu, Helenistik sanatın neşeli dekoratif yönünü temsil eder.'),
  ('Münih Glyptothek\'te sergilenen, kayanın üzerine kendinden geçmişçesine yayılarak uyuyan kaslı bir kır cinini cüretkar ve doğal bir erotizmle betimleyen MÖ 220 tarihli Helenistik heykel hangisidir?', 'Barberini Faunu', ['Doryphoros', 'Delphi Arabacısı', 'Kleobis ve Biton'], 'Bilinçdışı uyku halini, huzursuz yüz ifadesini ve gevşeyip gerilen kas zıtlığını işleyen Barberini Faunu, Helenistik Barok üslubunun başyapıtlarındandır.'),
  ('Lysippos\'un kayıp bir bronz orijinalinden Glykon tarafından kopyalanan, sopasına yaslanmış aşırı şişkin kaslı dev kahramanı bitkin halde ve arkasındaki elinde Hesperidler\'in elmalarını saklarken gösteren heykel hangisidir?', 'Farnese Herakles\'i', ['Apoksiomenos', 'Diskobolos', 'Tiran Katilleri'], 'İzleyiciyi elindeki elmaları görmek için heykelin arkasına dolanmaya teşvik eden Farnese Herakles\'i, süper kahramanın insani yorgunluğunu abartılı kaslarla tezat içinde sunar.'),
  ('Antik Yunan sanatında belden yukarısı insan, belden aşağısı dört ayaklı at gövdesi biçiminde betimlenen ve genellikle uygarlık dışı taşkın doğayı simgeleyen mitolojik yaratıklara ne ad verilir?', 'Kentaur', ['Minotauros', 'Sfenks', 'Khimaira'], 'Parthenon metoplarında ve Olympia batı alınlığında Lapithlerin düğününe saldıran Kentaurlar, dizginlenemeyen vahşi içgüdülerin simgesidir.'),
  ('Pheidias\'ın Athena Parthenos heykelinin göğsünde taşıdığı, keçi derisinden yapılmış saçaklı ve ortasında Medusa başı (Gorgoneion) bulunan koruyucu tanrısal zırh/pelerin öğesine ne ad verilir?', 'Aegis', ['Khiton', 'Strigilis', 'Kerykeion'], 'Zeus ve özellikle bilgelik-savaş tanrıçası Athena\'nın ayırt edici ikonografik zırh örtüsüne Aegis adı verilir.'),
  ('MÖ 6. yüzyılın ortalarında Atina\'da etkinlik gösteren, neşeli Dionysos alaylarını, satirleri ve maenadları zarif ve incelikli kazıma çizgileriyle işleyen siyah figür ustası kimdir?', 'Amasis Ressamı', ['Niobid Ressamı', 'Meidias Ressamı', 'Polignotos'], 'Çömlekçi Amasis\'in imzaladığı kapları bezeyen Amasis Ressamı, Eksekias\'ın ağırbaşlı trajik üslubunun karşısında zarif, dekoratif ve neşeli siyah figür tarzını temsil eder.'),
  ('Bir müzede sergilenen MÖ 500 tarihli vazoda kas çizgilerinin bir kısmı bal rengi seyreltik sırla hafif gölgeli, dış konturlar ise kabartma parlak siyah çizgiyle fırçalanarak kızıl kil zemin üzerine çizilmiştir; bu vazo hangi tekniktedir?', 'Kırmızı figür tekniği', ['Siyah figür tekniği', 'Oryantalizan silüet tekniği', 'Geometrik kazıma tekniği'], 'Kızıl kil renkte bırakılan figür üzerine fırçayla çekilen parlak siyah rölyef çizgisi ve seyreltilmiş altın-bal rengi kas çizgileri kırmızı figür tekniğinin imzasıdır.'),
  ('MÖ 8. yüzyıl Geometrik Dönem\'e ait ünlü "Dipylon Amforası"nın (Atina Ulusal Müzesi) gövdesindeki ana frizde şematik insan silüetleriyle betimlenen cenaze sahnesine ne ad verilir?', 'Prothesis (Ölünün katafalkta sergilenip ağıt yakılması)', ['Symposion (Şaraplı gece şöleni)', 'Gigantomakhia (Tanrılar ve devler savaşı)', 'Apoteoz (Kahramanın tanrılar katına yükselişi)'], 'Boyu 1,55 metreyi bulan Dipylon mezar amforasında ölü yatağının (kline) çevresinde ellerini başlarına götürerek saçlarını yolan ağıtçıların yer aldığı "prothesis" töreni resmedilmiştir.'),
  ('Aغaç gövdesine tırmanan küçük bir kertenkeleyi elindeki okla vurmaya hazırlanan zarif ve genç tanrıyı betimleyen Praksiteles heykeli hangisidir?', 'Apollon Sauroktonos', ['Belvedere Apollonu', 'Piombino Apollonu', 'Kassel Apollonu'], 'Praksiteles bu eserde korkutucu ejderha Python\'u öldüren yüce Apollon mitini, ağaçtaki küçük bir kertenkeleyle oynayan zarif bir delikanlıya dönüştürerek insancıllaştırmıştır.'),
  ('Antik Yunan sanatının Arkaik Dönem\'den Helenistik Dönem sonuna kadar geçirdiği yaklaşık altı yüzyıllık biçimsel evrim tek bir kavramsal çizgiyle özetlenirse en doğru sıralama hangisidir?', 'Katı simetrik şemadan ideal matematiksel dengeye, oradan da dramatik duygu ve bireysel gerçekçiliğe geçiş', ['Tamamen gerçekçi portrelerden başlayıp soyut geometrik kalıplara doğru kademeli sadeleşme', 'Yalnızca dini korku uyandıran dev heykellerden başlayıp tamamen figürsüz bitkisel mimariye yöneliş', 'Üç boyutlu sarmal hareketten başlayıp Mısır tipi tek cepheli hareketsiz blok heykellere dönüş'], 'Arkaik Dönem kuralcı ve cepheseldir; Klasik Dönem kontrapost ve Kanon ile ideal dengeyi (ethos) kurar; Helenistik Dönem ise dinamik hareket, acı (pathos) ve gerçekçiliğe açılır.'),
  ('Klasik Dönem Yunan tapınağı bağımsız bir heykel gibi doğanın ortasında her yönden algılanacak biçimde konumlanırken Helenistik Dönem tapınak ve sunak yerleşimlerinde (örneğin Bergama ve Kos Asklepieionu) nasıl bir değişim görülür?', 'Yapılar teraslar, stoalar ve anıtsal merdivenlerle birbirine bağlanarak izleyiciyi yönlendiren sahnesel ve eksensel mimari komplekslere dönüşmüştür', ['Tapınaklar kent dışındaki dağ tepelerinden indirilip tamamen yeraltı tünellerinin içine gizlenmiştir', 'Sütunlu revaklar ve basamaklar kaldırılarak tapınaklar çamur tuğladan tek odalı kulübelere indirgenmiştir', 'Her kentte yalnızca tek bir dairesel tholos yapılmasına izin verilip dikdörtgen planlar terk edilmiştir'], 'Helenistik şehircilik ve mimarlık (Kos, Lindos, Bergama gibi örneklerde), dramatik teraslamalar ve sütunlu avlularla yapıyı doğaya hükmeden tiyatral bir sahne dekoru gibi kurgulamıştır.'),
  ('Yeni Babil Dönemi Kralı II. Nebukadnezar zamanında inşa edilen ve mavi sırlı tuğlalar üzerindeki kabartmalarıyla tanınan ünlü anıtsal giriş hangisidir?', 'İştar Kapısı', ['Aslanlı Kapı', 'Güneş Kapısı', 'Kral Kapısı'], 'Babil\'in iç kentine giriş sağlayan İştar Kapısı, kobalt mavisi sırlı tuğlalar üzerine işlenmiş ejderha ve boğa kabartmalarıyla ünlüdür.'),
  ('Babil İştar Kapısı\'nın sırlı tuğla yüzeylerinde tanrı Marduk\'u simgeleyen boynuzlu, pullu gövdeli ve yırtıcı kuş pençeli mitolojik yaratık hangisidir?', 'Muşhuşşu', ['Lamassu', 'Grifon', 'Sfenks'], 'Babil\'in baş tanrısı Marduk\'un kutsal hayvanı olan Muşhuşşu ejderhası, İştar Kapısı üzerinde Fırtına Tanrısı Adad\'ın boğasıyla birlikte tasvir edilmiştir.'),
  ('Sümer adak heykellerinde (örneğin Tell Asmar heykelciklerinde) gözlerin normalden çok daha iri ve açık betimlenmesinin anlamı nedir?', 'İbadet eden kişinin tanrı karşısındaki sürekli uyanıklığını, saygısını ve ruhsal adanmışlığını yansıtmak', ['Heykeltraşların yüz oranlarını hesaplayacak anatomik gözlem bilgisinden tamamen yoksun bulunması', 'Karanlık tapınak odalarında içine yerleştirilen kandillerle etrafa ışık saçmasını sağlamak', 'Sümer soylularının genetik fiziksel özelliklerini abartısız bir gerçekçilikle kayda geçirmek'], 'Tapınaklara bırakılan Sümer adak heykellerinde iri, sedef ve lacivert taş kakmalı gözler tanrıyla kurulan kesintisiz ruhsal teması simgeler.'),
  ('Üzerinde savaş ve barış sahnelerinin lacivert taş (lapis lazuli) ve sedef kakmalarla üç yatay şerit hâlinde işlendiği Sümer eseri hangisidir?', 'Ur Standardı', ['Akbabalar Steli', 'Naram-Sin Steli', 'Gudea Heykeli'], 'Kraliyet mezarlarında bulunan Ur Standardı, bir yüzünde savaş diğer yüzünde şölen sahnelerinin kakma tekniğiyle anlatıldığı ahşap kasalı bir panodur.'),
  ('Yeni Sümer Dönemi\'nde Lagaş kenti yöneticisi olup sert diyorit taşından yapılmış çok sayıda oturan ve ayakta duran heykeliyle tanınan hükümdar kimdir?', 'Gudea', ['Ur-Nammu', 'Gılgamış', 'Asurbanipal'], 'Lagaş ensisi Gudea, ellerini göğsünde kavuşturmuş dindar duruşlu parlak siyah diyorit heykelleriyle Mezopotamya heykel sanatında önemli yer tutar.'),
  ('Asur Kralı Asurbanipal\'in Ninova\'daki Kuzey Sarayı duvarlarını süsleyen alçak kabartmalarda hangi sanatsal özellik öne çıkar?', 'Yaralı aslanların can çekişme anlarındaki kas gerilimlerinin yüksek bir doğalcılık ve dramatik güçle işlenmesi', ['İnsan figürlerinin doğadan kopuk, tamamen şematik ve hareketsiz dikdörtgen kütleler hâlinde yontulması', 'Yalnızca bitkisel kıvrımlar ile çivi yazılı duaların yer aldığı figürsüz bir bezeme anlayışının benimsenmesi', 'Derinlik algısı yaratmak için Rönesans dönemindeki çizgisel kaçış noktası perspektifinin eksiksiz uygulanması'], 'Asurbanipal\'in aslan avı kabartmaları, özellikle okla vurulmuş aslanların acı ve hareket dolu anatomik betimlemeleriyle antik sanatın zirvelerindendir.'),
  ('Sümer kenti Uruk\'ta bulunan ve Mezopotamya\'da kireçtaşından yapılmış en erken gerçek boyutlu insan yüzü betimlemelerinden biri kabul edilen eser hangisidir?', 'Warka Maskesi', ['Nefertiti Büstü', 'Agamemnon Maskesi', 'Sargon\'un Tunç Başı'], 'MÖ 4. binyıl sonuna tarihlenen mermer/kireçtaşı Warka Başı, kaş ve göz çukurları değerli taş kakmalarla tamamlanan erken bir Sümer başyapıtıdır.'),
  ('Üzerinde tanrıça İnanna\'ya sunulan tarımsal hediyelerin yatay kuşaklar hâlinde alçak kabartmayla anlatıldığı yaklaşık bir metre boyundaki kaymaktaşı kap hangisidir?', 'Warka Vazosu', ['Gümüş Entemena Vazosu', 'Kamares Vazosu', 'Dipylon Krateri'], 'Uruk\'ta bulunan Warka Vazosu, alttan üste doğru su, bitkiler, hayvanlar, sunu taşıyanlar ve en üstte İnanna\'yı gösteren anlatımcı kabartmanın öncüsüdür.'),
  ('Bir müzede sergilenen antik Mezopotamya heykelinde figürün kaslı bacakları abartılı biçimde belirginleştirilmiş, sakalı simetrik buklelerle örülmüş ve başında boynuzlu bir başlık varsa bu başlık neyi gösterir?', 'Betimlenen varlığın tanrısal bir kimliğe veya koruyucu ilahi statüye sahip olduğunu', ['Figürün tarım ve hayvancılıkla uğraşan sıradan bir taşra köylüsünü temsil ettiğini', 'Heykelin savaşta esir düşerek köleleştirilmiş yabancı bir kavim liderine ait olduğunu', 'Eserin Mezopotamya dışında, Eski Mısır\'ın Nil Deltası atölyelerinde üretildiğini'], 'Mezopotamya ikonografisinde boynuzlu taç veya başlık ilahiliğin temel alametidir; boynuz sayısı arttıkça tanrının rütbesi de yükselir.'),
  ('Hattuşa yakınlarında doğal kayalık galeriler içine altmıştan fazla Hitit tanrı ve tanrıçasının alçak kabartmayla işlendiği açık hava tapınağı hangisidir?', 'Yazılıkaya Açık Hava Tapınağı', ['İvriz Kaya Anıtı', 'Eflatunpınar Kutsal Havuzu', 'Gordion Tümülüsü'], 'Boğazköy\'deki Yazılıkaya, A ve B odalarındaki kaya yüzeylerine sıralı tanrılar alayının ve Kral IV. Tuthaliya\'nın işlendiği Hitit açık hava mabedidir.'),
  ('Hattuşa\'daki Kral Kapısı\'nda yer alan "Savaşçı Tanrı" kabartmasında figürün başının ve ayaklarının profilden, göğsünün cepheden işlenmesi hangi etkileşimi gösterir?', 'Hitit sanatının Yakın Doğu ve Mısır kökenli tasvir kalıplarını kendi yüksek kabartma anlayışıyla birleştirdiğini', ['Hitit taş ustalarının Yunan klasik dönemindeki kontrapost duruşunu birebir kopya ettiklerini', 'Kabartmanın Roma İmparatorluğu döneminde lejyoner askerler tarafından baştan yontulduğunu', 'Anadolu\'da maden çağlarından önce yalnızca mağara duvarı boyamacılığının bilindiğini'], 'Hitit kabartmalarında baş ve bacakların yandan, gövdenin cepheden verilmesi Mısır ve Mezopotamya ortak Yakın Doğu tasvir geleneğiyle paraleldir; ancak plastik hacim daha yüksektir.'),
  ('Şanlıurfa yakınlarında yer alan ve üzerlerinde tilki, yaban domuzu, akrep ve turna gibi hayvan kabartmaları bulunan T biçimli dikilitaşlarıyla ünlü merkez hangisidir?', 'Göbeklitepe', ['Alacahöyük', 'Kültepe', 'Beycesultan'], 'Çanak Çömleksiz Neolitik Dönem\'e tarihlenen Göbeklitepe, kireçtaşından T biçimli anıtsal dikilitaşları ve yüksek/alçak hayvan kabartmalarıyla tanınır.'),
  ('Konya Ereğli yakınlarındaki Geç Hitit (Tabal Krallığı) dönemine ait İvriz Kaya Anıtı\'nda Kral Warpalawas kimin karşısında dua ederken betimlenmiştir?', 'Bereket ve Fırtına Tanrısı Tarhunzas\'ın', ['Güneş Tanrısı Şamaş\'ın', 'Bilgelik Tanrısı Enki\'nin', 'Savaş Tanrıçası İştar\'ın'], 'İvriz Kaya Kabartması\'nda elinde üzüm salkımı ve buğday başakları tutan dev boyutlu Bereket Tanrısı Tarhunzas ile karşısında daha küçük boyutta Kral Warpalawas yer alır.'),
  ('Doğu Anadolu\'da Van Gölü çevresinde gelişen Urartu görsel sanatında özellikle hangi malzeme ve el sanatı dalı Yakın Doğu ve Akdeniz\'e ihraç edilecek düzeyde ustalaşmıştır?', 'Tunç kazanlar, kemerler ve fildişi oymacılığı', ['Porselen vazo üretimi ve ipek dokumacılığı', 'Sırlı mavi tuğla kaplamacılığı ve cam üfleme', 'Papirüs üzerine suluboya minyatür ressamlığı'], 'Urartular zengin maden yatakları sayesinde kanatlı siren/boğa eklentili tunç kazanlar, kabartmalı tunç kemerler ve kalkanlarda üstün ustalık sergilemiştir.'),
  ('Frigya başkenti Gordion\'daki büyük tümülüs mezar odasında keşfedilen zemin kaplamaları, Anadolu sanat tarihinde hangi tekniğin en erken örneklerinden sayılır?', 'Doğal çakıl taşı mozaik', ['Yağlıboya ahşap pano', 'Vitrifiye çini kaplama', 'Altın varaklı cam mozaik'], 'MÖ 8.-9. yüzyıllara tarihlenen Gordion çakıl taşı mozaikleri, renkli dere taşlarıyla oluşturulmuş geometrik desenleriyle bilinen en eski zemin mozaiklerindendir.'),
  ('Beyşehir Gölü yakınlarında kesme bazalt/andezit bloklarla inşa edilmiş, kabartmalı tanrı ve kanatlı güneş kursu figürleriyle bezeli Hitit su anıtı hangisidir?', 'Eflatunpınar Hitit Su Anıtı', ['Aizanoi Zeus Tapınağı', 'Aspendos Su Kemeri', 'Yerebatan Sarnıcı'], 'Konya Beyşehir\'deki Eflatunpınar, kutsal bir havuzun kenarında yükselen, Fırtına Tanrısı, Güneş Tanrıçası ve dağ tanrılarının taşıdığı kanatlı güneş kursu kabartmalarıyla ünlüdür.'),
  ('Urartu kalelerindeki Haldi tapınaklarının kare planlı, kalın köşe kuleli (rizalitli) taş duvarları ve iç duvarlarındaki mavi-kırmızı freskler neyi kanıtlar?', 'Urartuların hem sarp iklime dayanıklı savunma mimarisini hem de renkli saray-tapınak resim sanatını bir arada geliştirdiğini', ['Urartu ustalarının taş yontmayı bilmedikleri için tapınaklarını tamamen çadır bezinden kurduklarını', 'Doğu Anadolu\'daki tüm tapınakların Mısırlı mimarlar tarafından Nil kıyısındaki papirüs sütunlarla inşa edildiğini', 'Urartu dininde renk kullanımının yasaklanıp yalnızca sıvasız siyah bazalt yüzeylere izin verildiğini'], 'Altıntepe, Çavuştepe ve Ayanis gibi Urartu merkezlerinde kesme taş kuleli tapınaklar (susi) mavi, kırmızı ve beyaz duvar resimleri ve kakma süslemelerle bezenmiştir.'),
  ('Asur saraylarının koridorlarını boydan boya kaplayan taş ortostat kabartmalarında kuşatma makineleri, esir kafileleri ve vergi getiren elçilerin ayrıntılı işlenmesinin amacı nedir?', 'Saraya gelen yabancı elçiler ve tebaa üzerinde imparatorluğun yenilmezliği duygusunu uyandırmak', ['Okuma yazma bilmeyen taş ustalarına çivi yazısı alfabesini resimli bilmecelerle öğretmek', 'Ölen kralın ruhunun yeraltı dünyasında tarım yapabilmesi için büyüsel hizmetkârlar yaratmak', 'Askeri taktik sırlarını düşman krallıkların casuslarıyla açıkça paylaşarak barışı korumak'], 'Nimrud, Horsabad ve Ninova saraylarındaki alçak kabartmalar, kralın kabul salonuna yürüyen elçileri psikolojik olarak etkilemek üzere kurgulanmış görsel propagandalardır.'),
  ('Kuzey Suriye/Mezopotamya\'daki Mari Sarayı\'nda (Zimri-Lim Sarayı) günümüze ulaşan "Mari\'nin Taç Giydirme (Yetkilendirme) Sahnesi" hangi teknikle yapılmıştır?', 'Sıva üzerine duvar resmi', ['Sırlı tuğla yüksek kabartma', 'Altın ve fildişi kakma heykel', 'Renkli cam mozaik kaplama'], 'MÖ 18. yüzyıla ait Mari Sarayı duvar resimleri, Mezopotamya\'da nadir korunan büyük boyutlu anıtsal boyama sanatının en önemli örneğidir.'),
  ('Asur Kralı III. Şalmaneser\'e ait olan ve İsrail Kralı Yehu\'nun da aralarında bulunduğu yabancı hükümdarların haraç sunuşunu dört yüzünde yirmi pano hâlinde gösteren eser hangisidir?', 'Nimrud Siyah Dikilitaşı', ['Rosetta Taşı', 'Mesha Steli', 'Kiros Silindiri'], 'Nimrud\'da bulunan siyah kireçtaşı dikilitaş, basamaklı ziggurat tepeli formu ve haraç sahneleriyle Asur anıtsal taş yontuculuğunun önemli belgelerindendir.'),
  ('Bir kazıda bulunan Sümer mühür baskısında, omuzlarından su akıntıları fışkıran ve bu sularda balıkların yüzdüğü sakallı bir tanrı figürü görülüyorsa bu tanrı kimdir?', 'Bilgelik ve tatlı sular tanrısı Enki (Ea)', ['Fırtına ve savaş tanrısı Enlil', 'Yeraltı kraliçesi Ereşkigal', 'Ay tanrısı Nanna (Sin)'], 'Mezopotamya ikonografisinde omuzlarından balıklarla dolu Dicle ve Fırat nehirlerinin aktığı tanrı her zaman tatlı su ve bilgelik tanrısı Enki\'dir (Akadca Ea).'),
  ('Alacahöyük Sfenksli Kapı\'nın yan duvarlarındaki ortostat kabartmalarında Kral ve Kraliçe\'nin ellerini kaldırarak hangi kutsal hayvan heykelinin önünde ibadet ettiği görülür?', 'Sunak üzerindeki Fırtına Tanrısı\'nın boğası önünde', ['Kanatlı bir deniz ejderhası önünde', 'Yedi başlı bir yılan heykeli önünde', 'Tahtta oturan çakal başlı Anubis önünde'], 'Alacahöyük kabartmalarında Hitit Kralı ve Kraliçesi Tavananna, kaide üzerindeki boğa (Fırtına Tanrısı simgesi) karşısında dini tören yürütürken tasvir edilmiştir.'),
  ('Sümer tapınaklarının ve zigguratlarının dış kerpiç duvarlarında düzenli aralıklarla içeri-dışarı girinti ve çıkıntılar (payanda ve nişler) yapılmasının estetik ve teknik işlevi nedir?', 'Yeknesak kerpiç cephede ışık-gölge hareketi yaratırken aynı zamanda kalın duvarları statik olarak desteklemek', ['Düşman okçularının duvarlara merdiven dayamasını tamamen imkânsız kılan gizli tuzak kapıları oluşturmak', 'Yılda bir kez tapınak etrafında düzenlenen at arabası yarışlarında seyircilere oturma locası sağlamak', 'Yağmur sularını tapınağın tam ortasındaki kutsal sunak ateşinin üzerine yönlendirip söndürmek'], 'Mezopotamya tapınak cephelerindeki dikey girinti-çıkıntı (niş-payanda) düzeni hem duvara mukavemet kazandırır hem de güneş altında ritmik ışık-gölge etkisi üretir.'),
  ('Asur Kralı II. Aşurnasirpal\'in Nimrud (Kalhu) Kuzeybatı Sarayı\'nda kralı hayat ağacının yanında kanatlı koruyucu cinlerle (apkallu) birlikte gösteren sahnede cinlerin elindeki çam kozalağı ne işe yarar?', 'Kutsama ve arındırma ritüelinde kovadaki kutsal suyu ağaca ve krala serpmeye', ['Kralın taht odasında biriken böcek ve sinekleri kokulu reçine dumanıyla uzaklaştırmaya', 'Hasat mevsiminin başladığını halka duyurmak için tapınak çanına vurmaya', 'Yabancı elçilerin getirdiği altın külçelerin ağırlığını terazide dengelemeye'], 'Asur saray kabartmalarında kanatlı cinler (apkallu), bir ellerindeki situla (kova) içinden aldıkları kutsal sıvıyı diğer ellerindeki kozalakla serperek kralı ve kutsal ağacı kutsar.'),
  ('Hitit seramik sanatının başyapıtlarından olan "İnandıktepe Vazosu" üzerinde müzisyenler, akrobatlar, kurban sahnesi ve kutsal evlilik töreninin dört friz hâlinde kabartmayla işlenmesi neyi gösterir?', 'Dini bayram ve ritüellerin aşamalı bir öyküleme düzeniyle üç boyutlu kap yüzeyine aktarıldığını', ['Kabın yalnızca zeytinyağı taşımak için seri kalıplarla özensizce üretilmiş ticari bir amfora olduğunu', 'Hititlerde müzik ve dansın tapınak sınırları içinde ölüm cezasıyla yasaklanmış günahlar sayıldığını', 'Anadolu çömlekçilerinin boyalı bezemeyi tamamen bilmedikleri için kili çiğ bıraktıklarını'], 'Çankırı İnandıktepe\'de bulunan kabartmalı ve çok renkli (polikrom) vazo, Eski Hitit Dönemi\'nde bir kutsal evlilik (hieros gamos) şenliğini sinematografik şeritlerle anlatır.'),
  ('Ur Kral Mezarları\'nda Kraliçe Puabi\'nin mezarında bulunan, altın ve lacivert taşlarla süslü boğa başı figürü taşıyan ünlü müzik aleti hangisidir?', 'Ur Liri', ['Aulos flütü', 'Pan kavalı', 'Sistrum çıngırağı'], 'Sümer maden ve taş kakma işçiliğinin şaheserlerinden olan Ur Lirleri, rezonans kutusu üzerindeki hayvan masalları kakmaları ve altın boğa başlarıyla ünlüdür.'),
  ('Bir sanat tarihi öğrencisi incelediği antik kabartmada kartal başlı, kanatlı, kaslı insan gövdeli bir figürün kutsal bir hurma/hayat ağacı önünde durduğunu görüyorsa bu eseri hangi uygarlığa tarihlendirmelidir?', 'Yeni Asur İmparatorluğu\'na', ['Eski Krallık Mısır\'ına', 'Neolitik Çatalhöyük\'e', 'Klasik Dönem Atina\'sına'], 'Kartal başlı ve kanatlı koruyucu cinlerin (apkallu) stilize hayat ağacını kutsadığı ortostat kabartmaları, MÖ 9. yüzyıl Yeni Asur (özellikle Nimrud) sanatının imzası niteliğindedir.'),
  ('Hattuşa\'da bulunan "Hüseyindede" ve "Bitik" vazolarının ortak sanatsal özelliği aşağıdakilerden hangisidir?', 'Kırmızı parlak astarlı gövdeleri üzerinde dini tören ve dans sahnelerini gösteren renkli kabartmalı kuşaklar taşıması', ['Tamamen şeffaf dağ kristalinden oyularak içlerine altın tozlu çivi yazıları kazınmış olması', 'Mısır firavunlarının savaş arabasıyla aslan avladığı hiyeroglif yazılı papirüs kopyaları barındırması', 'Yalnızca siyah zemin üzerine beyaz kazıma geometrik çizgilerle süslenmiş Neolitik çömlekler olması'], 'Bitik, İnandık ve Hüseyindede vazoları, Eski Hitit Dönemi\'nin kabartmalı ve çok renkli anlatımcı seramik geleneğini temsil eden başlıca ritüel kaplarıdır.'),
  ('Kudurru adı verilen Babil sınır taşlarının üst bölümlerine akrep, yılan, boynuzlu taç, ay, güneş ve yıldız gibi tanrı sembollerinin kazınmasının amacı nedir?', 'Arazi bağış sözleşmesini tanrıların gözetimine sunarak taşı yerinden oynatanları ilahi lanetle uyarmak', ['Çiftçilere hangi mevsimde hangi tahıl ürününü ekeceklerini gösteren resimli bir tarım takvimi hazırlamak', 'Gece yolculuk yapan kervanların yıldızlara bakarak yön bulmasını sağlayan taş pusulalar üretmek', 'Taş ocağındaki ustaların kendi lonca damgalarını kayda geçirip ücretlerini tahsil etmesini sağlamak'], 'Kudurru anıtlarındaki kabartma semboller panteondaki büyük tanrıları temsil eder; anlaşmayı bozan kişiyi bu tanrıların cezalandıracağına inanılırdı.'),
  ('Urartu sanatında mobilya aksamlarını ve kemerleri süsleyen kanatlı insan-boğa ve hayat ağacı motifleri, hangi komşu uygarlıkla olan yoğun sanatsal etkileşimi yansıtır?', 'Asur İmparatorluğu', ['Eski Krallık Mısır\'ı', 'Miken Yunanistan\'ı', 'İndus Vadisi Uygarlığı'], 'Güney komşuları Asurlularla sürekli savaş ve kültür teması hâlinde olan Urartular, saray sanatındaki kanatlı cin, aslan, boğa ve hayat ağacı repertuarını kendi üsluplarına uyarlamıştır.'),
  ('Anadolu\'da Hititlerin kutsal kenti Nerik veya Zippalanda ile de tartışılan, Alacahöyük\'teki tunç güneş kurslarında sıklıkla çerçeve içine alınan kutsal hayvanlar hangileridir?', 'Geyik ve boğa', ['Timsah ve su aygırı', 'Fil ve gergedan', 'Devekuşu ve şahin'], 'Hatti ve erken Hitit inanç dünyasını yansıtan Alacahöyük tunç standartlarında gökyüzü/evren kafesi içinde geyik ve boğa figürleri merkezi yer tutar.'),
  ('Bir arkeolog Anadolu\'da kazdığı bir demir çağı tümülüsünde ardıç ve sedir kütüklerinden geçme tekniğiyle yapılmış mezar odası ve çok sayıda tunç fibula (çengelli iğne) buluyorsa bu mezar hangi uygarlığa aittir?', 'Frig Uygarlığı\'na', ['Sümer Kent Devletleri\'ne', 'Akad İmparatorluğu\'na', 'Eski Mısır Orta Krallığı\'na'], 'Yığma toprak tepeler (tümülüsler) altındaki ahşap mezar odaları, kakmalı ahşap mobilyalar ve yaylı tunç çengelli iğneler (fibula) Frig sanatının karakteristik buluntularıdır.'),
  ('Babil\'de İştar Kapısı\'ndan başlayarak Marduk Tapınağı\'na uzanan "Tören Yolu"nun (Alay Yolu) iki yanındaki sırlı tuğla duvarlarda tekrarlanan koruyucu hayvan figürü hangisidir?', 'Kükreyerek yürüyen yeleli aslanlar', ['Kanatlarını açmış akbabalar', 'Su püskürten yunus balıkları', 'Boynuz tokuşturan dağ keçileri'], 'Tanrıça İştar\'ın kutsal hayvanı olan aslan, Babil Tören Yolu boyunca mavi sırlı fon üzerinde sarı ve beyaz renkli yürüyen kabartma dizileri hâlinde yer alır.'),
  ('Çatalhöyük duvar resimlerinde evlerin plan şemasına benzeyen kare bölmelerin arkasında patlayan iki zirveli bir dağın betimlendiği ünlü sahne hangi yanardağla ilişkilendirilir?', 'Hasan Dağı', ['Ağrı Dağı', 'Erciyes Dağı', 'Nemrut Kalderası'], 'Çatalhöyük\'te bulunan ve kimilerince leopar postu, kimilerince tarihin en erken kent planı/manzara resmi olarak yorumlanan duvar resmindeki çift zirveli dağ Hasan Dağı ile ilişkilendirilir.'),
  ('Eski Mısır resim ve alçak kabartmalarında insan figürünün başı ve bacakları profilden (yandan), gözü ve omuzları ise cepheden (önden) çizilmesine ne ad verilir?', 'Cephedenlik (frontalite / tam görünüş) ilkesi', ['Merkezi çizgisel perspektif kuralı', 'Doğalcı anatomik kısaltım tekniği', 'İzlenimci ışık kırılması üslubu'], 'Mısır iki boyutlu sanatında her uzvu en kolay tanınan ve en eksiksiz açısından gösterme kuralına sanat tarihinde frontalite veya birleşik görünüş yasası denir.'),
  ('Yukarı ve Aşağı Mısır\'ın birleşmesini iki yüzündeki alçak kabartmalarla simgeleyen ve Mısır görsel kanonlarının (hiyerarşik oran, kayıt şeritleri) yerleştiği ilk büyük eser hangisidir?', 'Narmer Paleti', ['Rosetta Taşı', 'Merneptah Steli', 'Amarna Mektupları'], 'MÖ 3100 civarına tarihlenen şist/arduvaz taşından Narmer Paleti, Kral Narmer\'i hem Beyaz Taç hem Kırmızı Taç ile düşmanını alt ederken gösterir.'),
  ('Bir Mısır mezar duvar resminde bataklıkta kuş avlayan soylu mezar sahibi dev boyutta, yanındaki eşi orta boyutta, kayığı çeken hizmetkârlar ise çok küçük boyutta çizilmişse burada hangi kural uygulanmıştır?', 'Hiyerarşik oran (toplumsal statüye göre boyutlandırma)', ['Optik uzaklık küçülmesi (geometrik perspektif)', 'Kronolojik yaş sıralaması (çocukluktan yaşlılığa geçiş)', 'Işık kaynağına yakınlık derecesine göre büyütme'], 'Eski Mısır sanatında figürlerin boyutu izleyiciye olan mesafelerini değil, toplumsal ve ilahi hiyerarşideki önem derecelerini gösterir.'),
  ('Amarna Dönemi görsel sanatını, kendisinden önceki ve sonraki geleneksel Mısır sanatından ayıran en belirgin biçimsel değişim aşağıdakilerden hangisidir?', 'İdealize edilmiş katı duruşlar yerine sarkık karınlı, ince boyunlu, uzamış kafataslı ifadeci bedensel özelliklerin ve aile içi samimiyetin işlenmesi', ['İnsan figürünün sanattan tamamen çıkarılarak mezar duvarlarının yalnızca siyah-beyaz hiyeroglif metinlerle kaplanması', 'Tüm kraliyet heykellerinin taş yerine yalnızca eritilmiş gümüş ve cam hamurundan minyatür boyda dökülmesi', 'Firavunun her zaman savaş arabası üzerinde düşman başlarını ezerken öfkeli ve kaslı bir dev olarak gösterilmesi'], 'Amarna üslubunda geleneksel idealizm kırılmış; Akhenaton\'un yumuşak hatlı, şişkin karınlı bedeni ile Nefertiti ve kızlarıyla olan şefkatli anları doğal hareketlerle betimlenmiştir.'),
  ('Akhenaton\'un ölümünden sonra tahta geçen çocuk firavun Tutankhamun döneminde görsel sanat ve din alanında hangi gelişme yaşanmıştır?', 'Amarna üslubunun aşırılıkları terk edilerek Amon kültüne ve geleneksel Mısır sanat kanonlarına geri dönülmüştür', ['Piramit inşaatları yeniden başlatılarak Gize\'deki Keops Piramidi\'nin iki katı büyüklüğünde yeni bir piramit yapılmıştır', 'Mısır tapınaklarındaki tüm heykeller yıkılarak Yunanistan\'dan mermer heykeltıraşlar getirtilmiştir', 'Mezar duvar resimleri yasaklanarak ölülerin yakılması ve küllerinin Nil Nehri\'ne savrulması benimsenmiştir'], 'Tutankhamun (ilk adıyla Tutankhaton) döneminde Teb başkentliğine ve Amon rahipliğine dönülmüş; ancak mezar eşyalarında Amarna\'nın zarif çizgisel duyarlılığı bir süre daha hissedilmiştir.'),
  ('Eski Mısır duvar resimlerinde erkek figürlerin ten renginin genellikle kızıl-kahverengi, kadın figürlerin ise açık sarı veya krem tonlarında boyanmasının toplumsal/sembolik nedeni nedir?', 'Erkeklerin güneş altında dış mekân işlerinde, soylu kadınların ise gölgeli iç mekânlarda bulunduğunu belirten geleneksel kodlama', ['Kızıl aşı boyasının yalnızca kraliyet erkekleri için kutsal sayılırken kadınlarda kullanılmasının büyüsel uğursuzluk getirmesi', 'Mısırlı erkeklerin tamamının Nübye kökenli, kadınların ise tamamının Girit Adası kökenli göçmenler olması', 'Sarı boyanın yalnızca keten kumaş üzerinde tutunup kireç sıvalı duvarlarda kendiliğinden kahverengiye dönüşmesi'], 'Rahotep ve Nofret heykellerinde de açıkça görüldüğü üzere ten rengi ayrımı, cinsiyete dayalı toplumsal yaşam alanlarını simgeleyen yerleşik bir sanat konvansiyonudur.'),
  ('Louvre Müzesi\'nde sergilenen Sakkara buluntusu ünlü "Oturan Kâtip" heykeli, firavun heykelleriyle karşılaştırıldığında hangi yönüyle ayrılır?', 'Gevşek karın derisi ve hafif sarkık göğüsleriyle idealize edilmemiş gerçekçi bir meslek insanı fizyonomisi sunmasıyla', ['Firavunlardan üç kat daha büyük yontularak başında çift krallık tacı ve sahte sakal taşımasıyla', 'Kireçtaşı yerine tamamen saf altından dökülüp yakut taşlarla kaplanmış olmasıyla', 'Ayakta sol ayağını öne atmış bir savaşçı olarak elinde tunç mızrak tutmasıyla'], 'Firavunlar tanrısal kusursuzluk ve atletik gençlikle yontulurken, daha alt statüdeki memur ve kâtip heykellerinde yaş ve mesleki oturuş kaynaklı gerçekçi beden ayrıntılarına izin verilmiştir.'),
  ('Deyrü\'l-Bahri\'de sarp kayalık yamaca yaslanan, sütunlu geniş teraslar ve rampalardan oluşan görkemli morg (cenaze) tapınağı hangi kadın firavun adına inşa edilmiştir?', 'Kraliçe Hatşepsut', ['Kraliçe Kleopatra', 'Kraliçe Nefertiti', 'Kraliçe Arsinoe'], 'Mimar Senenmut tarafından tasarlanan Deyrü\'l-Bahri\'deki Hatşepsut Tapınağı, doğayla uyumlu yatay teras mimarisi ve Punt Seferi kabartmalarıyla ünlüdür.'),
  ('Luksor yakınlarındaki Karnak Amon Tapınağı\'nda yüz otuz dört dev papirüs başlıklı sütunun çatıyı taşıdığı ünlü mimari bölüme ne ad verilir?', 'Hipostil Salon', ['Peristil Avlu', 'Kubbeli Bazilika', 'Megaron Odası'], 'I. Seti ve II. Ramses dönemlerinde tamamlanan Karnak Büyük Hipostil Salonu, sık dizilmiş devasa sütunlarıyla kutsal bataklıktan yükselen yaratılış ormanını simgeler.'),
  ('Mısır tapınak girişlerinin önüne çiftler hâlinde dikilen, tepesi piramitçik (piramidion) şeklinde biten, tek parça granitten yontulmuş dört köşe anıtsal sütunlara ne denir?', 'Obelisk', ['Karyatid', 'Stupa', 'Menhir'], 'Güneş Tanrısı Ra\'nın taşlaşmış ışınlarını simgeleyen obeliskler (örneğin İstanbul Sultanahmet\'teki III. Thutmose Dikilitaşı), Asvan granitinden yekpare kesilirdi.'),
  ('Eski Mısır mezar duvar resimlerinde ve "Ölüler Kitabı" papirüslerinde ölen kişinin kalbinin hakikat tüyü (Ma\'at) ile tartıldığı sahneyi yöneten çakal başlı tanrı kimdir?', 'Anubis', ['Horus', 'Sobek', 'Bastet'], 'Mumyalama ve mezarlıkların koruyucusu çakal başlı Anubis, Osiris\'in mahkemesinde ölünün kalbini Ma\'at\'ın devekuşu tüyüyle terazide tartar.'),
  ('Bir müzedeki Mısır heykelinde Firavun Kefren\'in başının arkasında kanatlarını açmış bir şahin (Horus) duruyorsa ve önden bakıldığında şahin neredeyse hiç görünmüyorsa heykeltıraş neyi başarmıştır?', 'Frontalite yasasını bozmadan firavunun ilahi koruma altındaki tanrı-kral kimliğini plastik bütünlük içinde kaynaştırmayı', ['Şahin figürünü firavundan gizleyerek rahiplerin siyasi darbe planını heykele şifrelemeyi', 'Taş bloğun arkasındaki derin çatlağı kuş kanatlarıyla yamayarak malzemeyi kurtarmayı', 'İzleyiciyi heykelin etrafında koşmaya zorlayan Helenistik dönem sarmal kompozisyonunu uygulamayı'], 'Kahire Müzesi\'ndeki ünlü diyorit Kefren heykelinde Horus şahini, önden cephesel bütünlüğü bozmayacak, yandan ise başlıkla bütünleşecek ustalıkta yerleştirilmiştir.'),
  ('Mumyalama işlemi sırasında çıkarılan mide, bağırsak, akciğer ve karaciğerin korunduğu, kapakları Horus\'un dört oğlunun (insan, babun, çakal, şahin) başları şeklinde yontulan kaplara ne denir?', 'Kanopik kavanozlar', ['Riton kapları', 'Amfora testileri', 'Krater kaseleri'], 'Kaymaktaşı veya kireçtaşından yapılan dörtlü kanopik kaplar (İmsety, Hapi, Duamutef, Qebehsenuef başlıklı), iç organları öteki dünya için muhafaza ederdi.'),
  ('Eski Mısır açık hava tapınaklarının dış cephelerinde "yüksek kabartma" yerine konturları taşın içine doğru oyulan "batık kabartma" (sunk relief) tercih edilmesinin teknik ve görsel nedeni nedir?', 'Parlak Mısır güneşi altında derin gölge çizgileri oluşturarak figürlerin uzaktan net okunmasını ve dış aşınmadan korunmasını sağlamak', ['Batık kabartma yapmanın yüksek kabartmaya göre on kat daha fazla taş yontma emeği gerektirmesiyle zenginlik gösterisi yapmak', 'İçine kurşun eritilip dökülerek duvarların yıldırımdan korunmasını sağlamak', 'Kabartmaların gece karanlığında fosforlu boyalarla parlaması için çukur hazneler açmak'], 'Güneş ışığının çok dik ve sert vurduğu Mısır\'da normal alçak kabartmalar silikleşirken, kenarları oyulmuş batık kabartma keskin kontur gölgeleri yaratır.'),
  ('Amarna Dönemi\'ne ait bir kireçtaşı aile stelinde Akhenaton ve Nefertiti\'nin kucaklarındaki küçük prensesleri öperken tepedeki güneş kursu Aton\'dan uzanan ışınların ucunda küçük "eller" bulunması neyi anlatır?', 'Tek tanrısal güç Aton\'un ışınlarıyla kraliyet ailesine doğrudan yaşam (Ankh) ve bereket sunduğunu', ['Güneş tutulması sırasında gökyüzündeki kötü cinlerin krallığın tacını çalmaya çalıştığını', 'Heykeltıraşın insan eli çizmeyi öğrenmek için boş kalan gökyüzü alanını karalama tahtası yaptığını', 'Yabancı ülkelerden gelen elçilerin firavuna uzaktan bağlılık yemini ettiğini'], 'Amarna ikonografisinde insan biçimli (antropomorfik) eski tanrılar kaldırılmış; Aton yalnızca uçları Ankh tutan ellerle biten ışınlı bir güneş diski olarak betimlenmiştir.'),
  ('Gize\'deki üçüncü büyük piramidin sahibi Firavun Mikerinos\'u (Menkaure) ortada Tanrıça Hathor ve bir eyalet (nom) tanrıçasıyla yan yana gösteren yeşilimsi gri şist/arduvaz heykel grubuna ne denir?', 'Mikerinos Üçlüsü', ['Laokoon Grubu', 'Amarna Aile Steli', 'Memnon Devleri'], 'Kahire ve Boston müzelerinde örnekleri bulunan Mikerinos Üçlüleri, yüksek kabartma ile tam heykel arasında duran kusursuz cilalı Eski Krallık heykel gruplarıdır.'),
  ('Krallar Vadisi\'nin yakınındaki Kraliçeler Vadisi\'nde (QV66) bulunan ve canlı renklerini ilk günkü gibi koruyan en görkemli Yeni Krallık duvar resimlerine sahip mezar kime aittir?', 'II. Ramses\'in büyük eşi Kraliçe Nefertari\'ye', ['IV. Amenhotep\'in eşi Kraliçe Nefertiti\'ye', 'Makedonyalı son hükümdar VII. Kleopatra\'ya', 'Eski Krallık kraliçesi Hetepheres\'e'], 'Kraliçe Nefertari\'nin mezarı (QV66), yıldızlı lacivert tavanı ve kraliçeyi İsis, Hathor ve Anubis ile gösteren zarif gölgelendirmeli duvar resimleriyle Mısır mezar sanatının şaheseridir.'),
  ('Bir sanat tarihçisi Eski Mısır\'dan kalma kireçtaşı kırıkları ve çömlek parçaları (ostrakon) üzerinde hızlı siyah-kırmızı fırça darbeleriyle çizilmiş komik hayvan masalları ve akrobat eskizleri inceliyorsa bunlar kimin ürünüdür?', 'Deyrü\'l-Medine\'de yaşayan kraliyet mezar ustalarının ve ressamlarının', ['İskenderiye Kütüphanesi\'nde geometri çalışan Yunan filozoflarının', 'Sina Yarımadası\'ndaki bakır madenlerinde çalışan okuryazar olmayan esirlerin', 'Babil\'den Mısır\'a sürgün edilmiş çivi yazısı kâtiplerinin'], 'Krallar Vadisi\'nin mezarlarını yapan zanaatkârların köyü Deyrü\'l-Medine\'de bulunan binlerce resimli ostrakon, resmi kanon dışındaki özgür eskiz ve mizah sanatını belgeler.'),
  ('Eski Krallık heykellerinden Sakkara\'da bulunan ahşap "Şeyh el-Beled" (Ka-aper) heykeli, malzeme ve duruş açısından hangi özelliğiyle tanınır?', 'Firavun olmayan tombul yapılı bir rahip-memuru elinde asasıyla yürürken gösteren gerçekçi ahşap işçiliğiyle', ['Beş metre boyunda saf granitten yontulmuş kanatlı bir sfenks olmasıyla', 'Üzeri tamamen mavi sırlı fayans çinilerle kaplanmış bir savaşçı heykeli olmasıyla', 'İki başı ve dört kolu bulunan mitolojik bir nehir tanrısını betimlemesiyle'], 'Kazı işçilerinin köy muhtarına benzeterek "Şeyh el-Beled" adını taktığı V. Hanedan rahibi Ka-aper\'in firavun inciri ağacından heykeli, Mısır\'da sivil gerçekçiliğin başyapıtıdır.'),
  ('Firavun Sneferu döneminde (IV. Hanedan başı) basamaklı piramitten düz yüzlü gerçek piramide geçiş aşamasında eğim açısı yarı yolda değiştirildiği için özgün bir form kazanan Dahşur\'daki yapı hangisidir?', 'Eğik Piramit', ['Kızıl Piramit', 'Kara Piramit', 'Unas Piramidi'], 'Mimarların inşaat sırasında statik çökme riskini fark edip eğim açısını 54 dereceden 43 dereceye düşürmesiyle Dahşur\'daki Eğik Piramit ortaya çıkmış, hemen ardından ilk tam düz yüzlü Kızıl Piramit başarılmıştır.'),
  ('Mısır heykeltıraşlığında taş bloktan yontulan heykellerde kolların gövdeye bitişik, bacak aralarının dolu ve sırtın bir taş sütuna dayalı bırakılmasının teknik ve estetik gerekçesi nedir?', 'Sert taşın kırılmasını önleyerek heykelin sonsuza dek sağlam kalmasını sağlamak ve kübik blok etkisini korumak', ['Demir keskilerin taşı delmeye gücünün yetmemesi yüzünden aralıkların boşaltılamaması', 'Heykellerin arkasına gizli su boruları döşeyerek ağızlarından şarap akıtmak istemeleri', 'Gölge oyunları oynatmak için heykelin arkasında düz bir perde yüzeyi bırakma zorunluluğu'], '"Ebediyet sanatı" olan Mısır heykeltıraşlığında uzuvların gövdeden kopmaması (Ka\'nın evinin bozulmaması) için boşluksuz, kapalı kütle anlayışı benimsenmiştir.'),
  ('Yeni Krallık kraliçesi Hatşepsut\'un birçok resmi heykelinde geleneksel kadın giysileri yerine "erkek firavun peştamalı ve takma tören sakalı" ile betimlenmesinin nedeni nedir?', 'Mısır krallık ideolojisinde tam firavunluk otoritesinin geleneksel eril ikonografiyle meşrulaştırılması', ['Heykellerin aslında babası I. Thutmose için yapılıp yanlışlıkla Hatşepsut\'un mezarına konulması', 'Mısır\'da kadın yüzü ve bedeni yontmanın rahipler meclisi tarafından yasaklanmış olması', 'Hatşepsut\'un yabancı düşman ordularını korkutmak için ömrü boyunca kimliğini gizlemesi'], 'Hatşepsut meşru "Firavun" (Yukarı ve Aşağı Mısır Kralı) unvanını aldığında, sanatsal kanon gereği krallık alameti olan Nemes, şendit peştamal ve takma sakalla yontulmuştur.'),
  ('Bir arkeoloji müzesindeki Mısır kabartmasında firavunun başında hem uzun kubbeli "Beyaz Taç" (Hedjet) hem de önü kıvrımlı "Kırmızı Taç" (Deşret) iç içe geçmiş olarak (Pschent) görülüyorsa bu neyi simgeler?', 'Hükümdarın hem Yukarı (Güney) Mısır\'ın hem de Aşağı (Kuzey) Mısır\'ın birleşik mutlak kralı olduğunu', ['Firavunun aynı zamanda Babil ve Hitit imparatorluklarını da vergiye bağladığını', 'Kralın hem başkomutan hem de başhekim unvanlarını tek elde topladığını', 'Ülkede iki kardeş firavunun dönüşümlü olarak tahtı paylaştığını'], 'Güney Mısır\'ın Beyaz Tacı ile Kuzey Mısır\'ın Kırmızı Tacı\'nın birleşiminden oluşan Çift Taç (Pschent / Sekhemty), iki ülkenin siyasal birliğini ifade eder.'),
  ('Eski Mısır el sanatlarında kum/kuvars tozunun alkali tuzlar ve bakır oksitle pişirilmesiyle elde edilen, parlak turkuaz-mavi sırlı yüzeyiyle su aygırı ve uşabti heykelciklerinde çok kullanılan malzeme nedir?', 'Mısır fayansı', ['Çin porseleni', 'Venedik murano camı', 'İznik çinisi'], 'Kil içermeyen kuvars esaslı seramik benzeri bir malzeme olan Mısır fayansı (örneğin ünlü mavi su aygırı "William"), Nil\'in bereketini ve yeniden doğuşu simgeleyen turkuaz rengiyle ünlüdür.'),
  ('Mısır tapınak pilonlarında firavunun sol eliyle saçlarından kavradığı bir grup yabancı düşmanın üzerine sağ elindeki topuzu kaldırdığı sahnenin (smiting scene) binlerce yıl değişmeden tekrarlanmasının anlamı nedir?', 'Firavunun kaosu (İsfet) ezerek evrensel ilahi düzen ve adaleti (Ma\'at) koruma görevini simgelemesi', ['Mısır ordusunda kılıç ve ok kullanımının yasaklanıp yalnızca taş topuz kullanılması', 'Her firavunun tahta çıkarken tapınak avlusunda gladyatör dövüşü yapmak zorunda olması', 'Aynı taş kalıbın bütün tapınaklara kiralanarak masraftan tasarruf edilmesi'], 'Narmer Paleti\'nden Roma dönemi tapınaklarına dek üç bin yıl süren "düşmanı topuzla kahretme" motifi, tarihsel bir savaştan çok kozmik düzenin (Ma\'at) kaos üzerindeki zaferini temsil eder.'),
  ('Teb\'deki Rekhmire veya Ramose gibi XVIII. Hanedan vezir mezarlarının duvarlarında resmi ölü gömme sahnelerinin yanı sıra hangi konuların ayrıntılı işlenmesi günlük yaşam hakkında eşsiz bilgi verir?', 'Tuğla döken işçiler, maden dökümcüleri, heykeltıraş atölyeleri ve Girit/Nübye elçilerinin vergi sunuşu', ['Uzaydan gelen kanatlı gemilerin piramit tepelerine iniş yaptığı mitolojik kehanetler', 'Denizaltı cam fanusları içinde Akdeniz mercanlarını toplayan sünger avcıları', 'Buzullarla kaplı kuzey ülkelerine yapılan kızaklı keşif yolculukları'], 'Vezir Rekhmire\'nin mezarı (TT100), Mısır zanaat kollarını, inşaat tekniklerini ve Ege\'den (Keftiu/Minos) gelen hediye taşıyıcılarını belgeleyen eşsiz duvar resimlerine sahiptir.'),
  ('MÖ 196 yılına tarihlenen ve üzerinde hiyeroglif, demotik ve Eski Yunanca olmak üzere üç yazı metni bulunması sayesinde Champollion\'un Mısır hiyerogliflerini çözmesini sağlayan bazalt/granodiyorit stel hangisidir?', 'Rosetta Taşı', ['Behistun Yazıtı', 'Hammurabi Steli', 'Palermo Taşı'], 'Fransızların Mısır seferi sırasında Reşid (Rosetta) kasabasında bulunan V. Ptolemaios kararnamesi yazılı Rosetta Taşı, 1822\'de Jean-François Champollion tarafından çözülmüştür.'),
  ('Bir müze ziyaretçisi incelediği antik Mısır tabutunda veya duvar resminde yeşil ya da siyah tenli, gövdesi beyaz mumya sargılı, elinde çoban değneği (heka) ve harman döveni (nekhakha) tutan bir tanrı görüyorsa bu kimdir?', 'Ölüler dünyasının hakimi ve yeniden diriliş tanrısı Osiris', ['Fırtına, çöl ve kargaşa tanrısı Seth', 'Güneşin öğle vaktindeki yakıcı gücü Tanrı Ra', 'Bilgelik, yazı ve hesap tanrısı ibis başlı Thoth'], 'Yeşil/siyah ten rengi Nil\'in bereketli alüvyonunu ve bitkisel yeniden canlanmayı simgeler; mumya sargılı ve krallık asaları taşıyan bu figür her zaman yeraltı tanrısı Osiris\'tir.'),
  ('Mısır sanatında inek kulaklı kadın veya boynuzları arasında güneş kursu taşıyan inek biçiminde betimlenen; aşkın, müziğin, anneliğin ve neşenin tanrıçası kimdir?', 'Hathor', ['Sekhmet', 'Ma\'at', 'Nut'], 'Narmer Paleti\'nin üst köşelerinden Dendera Tapınağı\'nın "Hathor başlıklı" (sistrum biçimli) sütunlarına dek görülen inek boynuzlu/kulaklı tanrıça Hathor\'dur.'),
  ('Gize\'deki Kefren Piramidi Külliyesi\'nin bileşenleri (Vadi Tapınağı, üstü kapalı Tören Yolu, Morg Tapınağı ve Piramit) birlikte değerlendirildiğinde Mısır piramit mimarisi hakkında ne söylenebilir?', 'Piramidin tek başına yalıtılmış bir anıt olmayıp Nil kıyısından başlayan ritüel geçit ve tapınaklarla bütünleşik bir cenaze kompleksi olduğu', ['Piramidin etrafındaki yapıların bin yıl sonra Romalılar tarafından hamam ve stadyum olarak eklendiği', 'Vadi Tapınağı\'nın piramit inşaatında çalışan kölelerin cezalandırıldığı bir hapishane olarak tasarlandığı', 'Tören Yolu\'nun Nil taşkınlarını çöle akıtmak için açılmış sıradan bir sulama kanalı olduğu'], 'Klasik Eski Krallık piramitleri; Nil kanalındaki Vadi Tapınağı\'nda mumyalamanın yapılması, kapalı rampa yoldan çıkılması ve Morg Tapınağı\'nda günlük sunuların sürdürülmesiyle işleyen bütünleşik külliyelerdir.'),
  ('Tutankhamun\'un mezarında bulunan "Ahşap Boyalı Sandık" üzerindeki savaş ve aslan avı sahneleri, geleneksel Mısır yatay şerit düzeninden hangi özelliğiyle ayrılır?', 'Düşmanların ve hayvanların üst üste karmaşık bir kaos yığını hâlinde savrulurken firavunun merkezde mutlak düzeni temsil etmesiyle', ['Sahnede hiçbir insan veya hayvan figürüne yer verilmeyip yalnızca mavi nilüfer çiçeklerinin sıralanmasıyla', 'Firavunun savaş arabasından düşerek yaralandığı trajik bir yenilgi anını gerçekçi biçimde göstermesiyle', 'Tamamen siyah-beyaz silüet tekniğiyle boyanıp renk kullanımından kaçınılmasıyla'], 'Tutankhamun\'un boyalı sandığında firavun düzenli ve dev boyutta ok atarken, karşısındaki Nübyeli/Asyalı düşmanlar yatay çizgiden kopmuş karmakarışık bir kaos (İsfet) içinde betimlenmiştir.'),
  ('Amarna Kenti\'ni birkaç yıl içinde hızla inşa edebilmek için Akhenaton dönemi mimarlarının geliştirdiği, bir işçinin tek başına omzunda taşıyabileceği standart küçük kireçtaşı bloklara arkeolojide ne ad verilir?', 'Talatat blokları', ['Ortostat levhaları', 'Megalit kayalar', 'Kiklopik taşlar'], 'Arapça "üç karış" anlamındaki kelimeden türetilen yaklaşık 52x26x24 cm boyutlarındaki standart "talatat" blokları, Amarna\'nın rekor sürede inşa edilmesini (ve sonra kolayca sökülmesini) sağlamıştır.'),
  ('MÖ 1274\'teki Kadeş Savaşı\'nı ve Firavun II. Ramses\'in Hitit ordusuna karşı savaş arabasındaki kahramanlığını devasa alçak/batık kabartmalarla anlatan tapınaklar arasında hangisi yer alır?', 'Ramesseum, Luksor ve Ebu Simbel tapınakları', ['Zoser Basamaklı Piramidi ve Meydum Mastabası', 'Amarna Küçük Aton Tapınağı ve İskenderiye Feneri', 'Dendera Hathor ve Kom Ombo Sobek tapınakları'], 'II. Ramses, Hititlerle yaptığı Kadeş Savaşı\'nı Karnak, Luksor, Ramesseum, Abydos ve Ebu Simbel tapınaklarının pilon ve duvarlarına dev görsel propaganda sahneleriyle kazıtmıştır.'),
  ('British Museum\'da korunan ve Tebli kâtip Ani için hazırlanmış yirmi üç metrelik resimli papirüs rulosu ("Ani Papirüsü"), Eski Mısır\'ın hangi dini-sanatsal türünün en ünlü örneğidir?', 'Ölüler Kitabı', ['Gılgamış Destanı', 'Yaratılış (Enuma Eliş) Metni', 'Tufan Efsanesi'], 'Özgün adı "Güne (Aydınlığa) Çıkış Büyüleri" olan Ölüler Kitabı\'nın en zengin resimli örneklerinden Ani Papirüsü, Yeni Krallık kitap ressamlığının zirvesidir.'),
  ('Eski Mısır mezar odalarında yer alan, taştan oyulmuş ancak açılmayan "Sahte Kapı" (False Door) mimari öğesinin görsel ve dinsel işlevi nedir?', 'Ölen kişinin ruhunun (Ka) yeraltı mezar odasından çıkıp sunu masasındaki yiyecek ve dualara ulaşmasını sağlayan büyüsel geçit olması', ['Mezar soyguncularını yanlış koridora yönlendirip üzerlerine kum tuzakları düşürmek için tasarlanması', 'Mimarın kapı menteşesi takmayı unuttuğu yarım kalmış inşaat hatasını simetrik göstermek istemesi', 'Rahiplerin duvarın arkasından seslenerek halka kehanet bildirdiği gizli akustik pencere olması'], 'Mastaba ve mezar şapellerinin batı duvarında yer alan Sahte Kapı, üzerinde mezar sahibinin yemek masası başındaki kabartmasıyla yaşayanlar dünyası ile ölüler alemi arasındaki temas noktasıdır.'),
  ('Eski Mısır sanatında zarif evcil kedi veya kedi başlı kadın olarak tasvir edilen, evi ve doğumu koruyan Aşağı Mısır (Bubastis) kökenli tanrıça kimdir?', 'Bastet', ['Sekhmet', 'Sobek', 'Taweret'], 'Tunçtan yapılmış zarif kedi heykelleriyle (örneğin kulağı altın küpeli Gayer-Anderson Kedisi) dünya müzelerinde tanınan tanrıça Bastet\'tir.'),
  ('Sümer zigguratlarında pişmemiş kerpiç çekirdeğin dışına pişmiş tuğla kaplanırken harç olarak su sızdırmazlığı sağlamak amacıyla bölgede bol bulunan hangi doğal madde kullanılmıştır?', 'Bitüm', ['Portlant çimentosu', 'Mermer tozu tutkalı', 'Çam reçinesi verniği'], 'Petrol yatakları bakımından zengin olan Mezopotamya\'da (Ur Zigguratı ve Babil yapılarında) tuğla örgüde nem yalıtımı ve bağlayıcı olarak doğal zift (bitüm) ve kamış hasırlar kullanılmıştır.'),
  ('Cumhuriyet Dönemi Roma büst portreciliğinde yaşlılık kırışıklıkları, kellik ve yüz kusurlarının abartılmadan tüm gerçekliğiyle betimlenmesi hangi sanat anlayışıyla adlandırılır?', 'Verizm', ['İdealizm ve klasik oran arayışı', 'Maniyerist deformasyon üslubu', 'Arkaik gülümseme geleneği'], 'Roma Cumhuriyet Dönemi portrelerinde deneyim ve bilgeliği simgeleyen kırışıklıkların olduğu gibi yansıtılmasına verizm (aşırı gerçekçilik) denir.'),
  ('Pantheon kubbesinin iç yüzeyinde yer alan kare biçimli kasetlerin (kofer) temel mimari ve statik işlevi aşağıdakilerden hangisidir?', 'Kubbenin ölü ağırlığını azaltırken görsel derinlik kazandırmak', ['Yağmur sularını dış cephedeki çörtenlere yönlendirmek', 'İç mekandaki ses yankısını artırarak akustiği güçlendirmek', 'Bronz heykellerin sabitlenmesi için niş alanı oluşturmak'], 'Kubbe tavanındaki kademeli kasetler hem betondan dökülen kubbenin ağırlığını hafifletir hem de perspektif etkisi yaratır.'),
  ('Alman arkeolog August Mau tarafından dört ana üsluba ayrılan Pompei duvar resimlerinde Birinci Üslup (İnkrüstasyon) neyi taklit eder?', 'Renkli mermer kaplamaları ve taş blok dizilimlerini boyalı sıva ile taklit etmeyi', ['Duvarı tamamen ortadan kaldırarak hayali mimari perspektifler açmayı', 'Mısır mitolojisinden alınan fantastik yaratıkları ince sütunlar üzerinde göstermeyi', 'Yalnızca siyah arka plan üzerine minyatür doğa manzaraları işlemeyi'], 'Birinci Pompei üslubu, pahalı mermer plakaları kabartmalı alçı ve canlı boyalarla taklit eden kaplama (inkrüstasyon) tarzıdır.'),
  ('İmparator Augustus\'u bir ordu komutanı olarak idealize edilmiş genç bir bedenle ve sağ kolunu kaldırarak askerlere hitap ederken (adlocutio) gösteren ünlü heykel hangisidir?', 'Prima Porta Augustus Heykeli', ['Marcus Aurelius Atlı Heykeli', 'Kapitolini Brutus Büstü', 'Caracalla Mermer Portresi'], 'Prima Porta\'da bulunan Augustus heykeli, Klasik Yunan Doryphoros oranlarını Roma siyasi propagandasıyla birleştiren adlocutio pozundadır.'),
  ('MS 70 yılındaki Kudüs Kuşatması\'nı ve Tapınak\'tan alınan Yedi Kollu Şamdan\'ın (Menora) Roma\'ya getirilişini iç kabartmalarında betimleyen anıt hangisidir?', 'Titus Zafer Takı', ['Septimius Severus Zafer Takı', 'Traianus Anıt Sütunu', 'Ara Pacis Barış Sunağı'], 'Roma Forumu girişindeki Titus Zafer Takı, kemer içi rölyeflerinde Kudüs\'ten getirilen ganimetlerin ve Menora\'nın taşındığı alayı gösterir.'),
  ('Roma\'daki Traianus Sütunu\'nun gövdesini aşağıdan yukarıya doğru sarmal bir şerit halinde dolanan yaklaşık iki yüz metrelik kabartma kuşağı hangi olayı anlatır?', 'İmparator Traianus\'un Daçyalılara karşı düzenlediği iki büyük askeri seferi', ['Hannibal komutasındaki Kartaca ordusunun Alpleri aşarak İtalya\'ya girişini', 'Jül Sezar\'ın Galya kabilelerini yenilgiye uğratıp Vercingetorix\'i esir alışını', 'İmparator Hadrianus\'un Britanya adasının kuzeyinde savunma duvarı inşa ettirmesini'], 'Traianus Sütunu\'ndaki kesintisiz friz, Daçya Savaşları\'nın hazırlık, köprü inşası, kuşatma ve zafer aşamalarını belgesel titizliğiyle işler.'),
  ('İmparator Augustus\'un Galya ve İspanya seferlerinden dönüşü onuruna Roma\'da inşa edilen, dış duvarları imparatorluk ailesinin dini tören alayı kabartmalarıyla süslü yapı hangisidir?', 'Ara Pacis Augustae (Augustus Barış Sunağı)', ['Domus Aurea (Altın Ev Sarayı)', 'Castel Sant\'Angelo Mozolesi', 'Caracalla Hamamları Kompleksi'], 'MÖ 9\'da kutsanan Ara Pacis Augustae, Pax Romana (Roma Barışı) döneminin bereketini ve hanedan üyelerinin katıldığı kurban alayını betimler.'),
  ('Mısır\'ın Roma eyaleti olduğu dönemde mumyaların yüz kısmına yerleştirilen ve "Fayyum Portreleri" olarak bilinen gerçekçi ahşap portrelerde ağırlıklı olarak hangi boyama tekniği kullanılmıştır?', 'Enkostik', ['Islak kireç sıva üzerine uygulanan buon fresko tekniği', 'Yumurta akı bağlayıcılı Orta Çağ tezhip tekniği', 'Yağlı boya ve keten tohumu yağı incelticili glazür tekniği'], 'Fayyum mumya portreleri, eritilmiş sıcak balmumunun renk pigmentleriyle karıştırılıp ahşap veya keten yüzeye sürüldüğü enkostik tekniğinin en canlı örnekleridir.'),
  ('Erken Hristiyan sanatında İsa\'nın henüz doğrudan çarmıhta acı çekerken betimlenmediği katakomp resimlerinde, omuzlarında bir kuzu veya koyun taşıyan gencin yer aldığı yaygın sembolik figür hangisidir?', 'İyi Çoban', ['Pantokrator İsa', 'Deesis (Yakarış) sahnesi', 'Anastasis (Diriliş) tasviri'], 'Antik Akdeniz\'deki kriophoros (buzağı/koç taşıyan) heykel tipinden uyarlanan İyi Çoban, ruhları kurtaran ve koruyan İsa\'yı simgeler.'),
  ('Erken Hristiyan katakomp ve lahit sanatında sıkça görülen "balık" (Yunanca İkhthys) figürünün Hristiyanlar tarafından gizli bir inanç sembolü olarak seçilmesinin temel nedeni nedir?', 'Yunanca balık kelimesinin harflerinin "İsa Mesih, Tanrı\'nın Oğlu, Kurtarıcı" ifadesinin baş harflerini (akrostiş) oluşturması', ['Aziz Petrus\'un Roma\'ya gelirken bir balina tarafından yutulup kurtarılması mucizesine dayanması', 'Vaftiz suyunun yalnızca deniz kenarındaki balıkçı köylerinden temin edilmesi zorunluluğu', 'Roma imparatorlarının sikkelerinde balık sembolünün kullanımının kesin olarak yasaklanmış olması'], 'Yunanca İKHTHYS kelimesi; İesous Khristos Theou Yios Soter sözcüklerinin baş harflerinden oluşan teolojik bir şifre niteliğindedir.'),
  ('Erken Hristiyan bazilikalarında orta nefin (ana koridorun) yan neflerden daha yüksek tutularak üst duvarlarına açılan ve iç mekanı aydınlatan pencere dizisine ne ad verilir?', 'Clerestory', ['Triforyum kör kemer dizisi', 'Narteks yan revakları', 'Ambon vaaz kürsüsü'], 'Orta nefin çatısının yan neflerden yükseltilmesiyle kazanılan duvar yüzeyindeki pencerelere clerestory (ışık katı) denir.'),
  ('Roma\'da İmparator Konstantin\'in kızı Constantina için MS 4. yüzyılda inşa edilen, merkezi dairesel planlı ve koridor tonozları bağbozumu mozaikleriyle kaplı anıt mezar yapısı hangisidir?', 'Santa Costanza Mozolesi', ['Galla Placidia Türbesi', 'Theoderik Anıt Mezarı', 'San Vitale Bazilikası'], 'Santa Costanza, Erken Hristiyan merkezi planlı mimarisinin en erken örneklerinden olup tonozlarındaki şarap yapımı mozaikleri hem antik Dionysos geleneğini hem Efkaristiya\'yı çağrıştırır.'),
  ('Roma yer mozaiklerinden farklı olarak Erken Hristiyan ve Bizans duvar mozaiklerinde cam tesseraların yüzeye tamamen düz değil de hafifçe farklı açılarla (eğimli) yerleştirilmesinin sanatsal amacı nedir?', 'Kandil ve gün ışığını farklı yönlere kırarak mekanda titreşimli, ruhani bir altın ışıltısı yaratmak', ['Deprem sarsıntılarında cam parçalarının birbirine sürtünerek dökülmesini engellemek', 'Duvarlardaki nemin harç arkasından dışarıya daha hızlı buharlaşmasını sağlamak', 'Aşağıdan bakan izleyicinin figürlerin yüz hatlarını hiç seçememesini sağlamak'], 'Altın ve gümüş yaprak sıkıştırılmış cam tesseralar hafif açılarla dizildiğinde ışığı sabit bir ayna gibi değil, parıldayan canlı bir yüzey gibi yansıtır.'),
  ('Ravenna\'daki en erken tarihli (MS 5. yüzyıl ortası) mozaik topluluğunu barındıran, dıştan sade tuğla görünümlü ancak içi lacivert yıldızlı gökyüzü ve İyi Çoban mozaikleriyle kaplı haç planlı yapı hangisidir?', 'Galla Placidia Mozolesi', ['San Marco Bazilikası', 'Aya İrini Kilisesi', 'Kariye Müzesi Parekklesionu'], 'Galla Placidia Mozolesi, sade tuğla dış cephesiyle keskin bir tezat oluşturan zengin iç mekan mozaikleriyle Erken Hristiyan sanatının başyapıtlarındandır.'),
  ('Ravenna\'da MS 547 yılında kutsanan, sekizgen merkezi planlı mimarisi ve apsis yan duvarlarındaki İmparator I. Justinianus ile İmparatoriçe Theodora mozaik panolarıyla ünlü kilise hangisidir?', 'San Vitale Kilisesi', ['Sant\'Apollinare in Classe', 'Santa Maria Maggiore', 'Aziz Sergios ve Bakhos Kilisesi'], 'San Vitale Kilisesi, Bizans\'ın İtalya\'daki en önemli mimari eseri olup Justinianus ve Theodora\'nın ayine sunu getirirken betimlendiği ünlü mozaikleri barındırır.'),
  ('San Vitale\'deki İmparatoriçe Theodora mozaiğinde, elinde şarap kadehi (kaliks) tutan imparatoriçenin erguvani pelerininin etek ucunda altın işlemeyle hangi sahne betimlenmiştir?', 'Bebek İsa\'ya hediyeler getiren Üç Müneccim Kral', ['Adem ile Havva\'nın Cennet Bahçesi\'nden kovuluşu', 'Başmelek Mikail\'in ejderhayı mızrakla alt edişi', 'Aziz Yuhanna\'nın İsa\'yı Ürdün Nehri\'nde vaftiz edişi'], 'Theodora kiliseye altın kadeh sunarken pelerininin eteğindeki Üç Müneccim Kral tasviri, onun da krallar gibi İsa\'ya değerli armağanlar sunduğunu ima eder.'),
  ('Ravenna\'daki Ostrogot Kralı Theoderik tarafından yaptırılan "Sant\'Apollinare Nuovo" Bazilikası\'nın nef duvarlarındaki mozaiklerde, Bizans fethi sonrasında yapılan siyasi müdahale nerede görülür?', 'Theoderik\'in sarayı (Palatium) kemerleri arasındaki figürlerin kazınarak yerlerine beyaz perdeler işlenmesinde ve sütunlarda kalan el izlerinde', ['Kilisenin tüm apsis mozaiklerinin siyah boyayla kapatılıp üzerine Latince yazıtlar yazılmasında', 'İsa\'nın yaşamını anlatan üst kuşak mozaiklerinin sökülerek Konstantinopolis\'e taşınmasında', 'Yalnızca kadın azizlerin yer aldığı tören alayının erkek asker figürleriyle değiştirilmesinde'], 'Bizanslılar Ravenna\'yı ele geçirince Ariusçu kral Theoderik ve saray erkânının tasvirlerini mozaikten kazımış, ancak sütun gövdelerinde figürlerin bazı elleri kalmıştır.'),
  ('Ayasofya mimarisinde kare planlı alt yapıdan dairesel ana kubbeye geçişi sağlayan ve dört büyük paye arasındaki kemerlerin köşelerini dolduran küresel üçgen mimari elemanlara ne ad verilir?', 'Pandantif', ['Tromp tonozu', 'Uçan payanda', 'Arşitrav kirişi'], 'Ayasofya, anıtsal ölçekte pandantifli kubbe sisteminin başarıyla uygulandığı en önemli yapıdır; küresel üçgen pandantifler kubbe yükünü dört ana payeye aktarır.'),
  ('Bizans mimarisinde Ayasofya ve Küçük Ayasofya (Sergios ve Bakhos) gibi yapılarda sütun başlıklarının mermer yüzeyinin matkapla derinlemesine oyularak dantel gibi işlenmesi tekniğiyle oluşan başlık türüne nasıl betimleme yapılır?', 'Sepet veya katlanmış dantel görünümlü oyma impost başlık', ['Arkaik Dorik yastık tablası başlığı', 'Mısır papirüs ve lotus tomurcuğu başlığı', 'Gotik yaprak kabartmalı gargoyle başlığı'], '6. yüzyıl Justinianus dönemi başlıklarında klasik akantus yaprakları hacmini kaybedip alttaki koyu gölge boşluğu üzerinde dantel gibi oyulmuş yüzeylere dönüşmüştür.'),
  ('Kolezyum\'un dört katlı dış cephesinde, antik mimarlık geleneğine uygun olarak zemin kattan üçüncü kata doğru yükseldikçe gömme sütunlarda hangi mimari düzen sırası uygulanmıştır?', 'Zeminde Toskana (Dorik), ikinci katta İyonik, üçüncü katta Korint düzeni', ['Zeminde Korint, ikinci katta İyonik, üçüncü katta Dorik düzeni', 'Tüm katlarda yalnızca Kompozit başlık ve sarmal sütun düzeni', 'Zeminde Mısır Hathor başlığı, üst katlarda Pers boğa başlıklı düzen'], 'Romalılar çok katlı cephelerde görsel ağırlıktan zarafete doğru; altta sade Toskana/Dorik, ortada kıvrımlı İyonik, üstte yapraklı Korint başlık dizilimini standartlaştırmıştır.'),
  ('Pompei\'deki "Vettii Evi" (Casa dei Vettii) duvarlarını süsleyen, mimari perspektiflerle düz panoları ve mitolojik tabloları zengin bir tiyatro dekoru gibi birleştiren resimler hangi Pompei üslubunun en ünlü örneğidir?', 'Dördüncü Üslup (Karma / Yanılsamacı Üslup)', ['Birinci Üslup (Mermer Taklidi Üslup)', 'Erken Geometrik Dönem Üslubu', 'Siyah Figürlü Vazo Üslubu'], 'MS 62 depreminden sonra yenilenen Vettii Evi, önceki üç üslubun öğelerini eklektik ve gösterişli biçimde sentezleyen Dördüncü Üslup\'un başyapıtıdır.'),
  ('Pompei\'deki "Faun Evi"nin (Casa del Fauno) tabanında bulunan ve Büyük İskender ile Pers Kralı III. Darius arasındaki İssos Savaşı\'nı betimleyen ünlü eserin tekniği nedir?', 'Opus vermiculatum tekniğinde çok küçük taşlarla yapılmış taban mozaiği', ['Sıcak balmumu ile ahşap üzerine yapılmış enkostik pano', 'Kırmızı kil üzerine kazıma tekniğiyle işlenmiş seramik levha', 'Kuru sıva üzerine tutkal boyayla yapılmış duvar freski'], 'İskender Mozaiği, milimetrik boyutlardaki milyonlarca renkli taş küpün (opus vermiculatum) fırça darbesi inceliğinde dizildiği Helenistik bir tablonun Roma kopyasıdır.'),
  ('İstanbul Sultanahmet Meydanı\'ndaki (antik Hipodrom) Dikilitaş\'ın altında yer alan mermer kaide kabartmalarında hangi Bizans imparatoru locada oturup yarışları izlerken ve kazananlara çelenk sunarken betimlenmiştir?', 'I. Theodosius', ['I. Justinianus', 'II. Basileios', 'Herakleios'], 'Mısır firavunu III. Thutmose\'ye ait granit obeliski MS 390\'da Hipodrom\'a diktiren İmparator I. Theodosius, mermer kaidenin dört yüzünde ailesi, muhafızları ve halkla birlikte hiyerarşik düzende işlenmiştir.'),
  ('Sina Dağı\'ndaki Azize Katerina Manastırı\'nda korunan ve İkonoklazm yıkımından kurtulan MS 6. yüzyıl tarihli ünlü "Pantokrator İsa" ikonasında İsa\'nın yüzünün sağ ve sol yarısının farklı ifadeler taşıması neyi simgeler?', 'İsa\'nın hem insani ve merhametli doğasını hem de ilahi ve adil yargıç doğasını', ['Ressamın eseri yarım bırakıp ölmesi üzerine bir öğrencisinin yüzün diğer yarısını farklı üslupla tamamlamasını', 'İkonanın yarısının yangında kararması nedeniyle Orta Çağ\'da hatalı bir restorasyon geçirmesini', 'Doğu ve Batı Roma kiliseleri arasındaki siyasi bölünmenin sanatsal bir eleştirisini'], 'Enkostik tekniğiyle yapılmış bu başyapıtta İsa\'nın kutsama işareti yapan tarafı sakin ve bağışlayıcı, İncil tutan diğer yüz yarısı ise sert ve yargılayıcı işlenerek Kalkedon Konsili\'nin çift doğa doktrini görselleştirilmiştir.'),
  ('726 yılında Konstantinopolis\'teki Büyük Saray\'ın Tunç Kapısı (Khalke) üzerindeki İsa ikonasını indirterek Bizans\'ta İkonoklazm sürecini resmen başlatan imparator kimdir?', 'III. Leon', ['Büyük Konstantin', 'I. Aleksios Komnenos', 'II. Mehmed'], 'İmparator III. Leon, doğal afetleri ve askeri tehditleri Tanrı\'nın tasvirlere tapınılmasına duyduğu öfkeye bağlayarak 726\'da İkonoklazm politikasını başlatmıştır.'),
  ('Bizans\'ta ikonaları savunan "İkonodul" (tasvir yanlısı) ilahiyatçılardan Şamlı Aziz Yuhanna, Tanrı\'nın görünmez olduğu gerekçesiyle İsa tasvirine karşı çıkanlara hangi temel teolojik argümanla yanıt vermiştir?', 'Tanrı\'nın Sözü İsa Mesih\'te bedenleşip görünür insan olduğu (enkarnasyon) için onun maddi suretinin çizilebilir olduğu teziyle', ['Resimlerin yalnızca okuma yazma bilmeyen barbar kavimleri korkutmak için geçici bir araç olduğu görüşüyle', 'Sanatçıların resim yaparken kendi iradeleriyle değil meleklerin ellerini tutmasıyla hareket ettiği inancıyla', 'Eski Yunan filozoflarının heykellere tapınmayı akılcı bulduğu yönündeki antik felsefe metinleriyle'], 'Şamlı Yuhanna\'ya göre Eski Ahit\'teki tasvir yasağı görünmez Tanrı içindi; ancak Tanrı İsa\'da et ve kemik olarak görünür hale geldiğinden onu resmetmek bedenleşmeyi doğrulamaktır.'),
  ('İkonoklazm\'ın sona ermesinin ardından 867 yılında Ayasofya\'nın apsis yarım kubbesine yapılan ve Patrik Photios\'un vaazıyla açılan ilk büyük figürlü mozaikte kimler betimlenmiştir?', 'Tahtta oturan Meryem Ana ve kucağındaki Çocuk İsa', ['Çarmıha gerilmiş İsa ve haçın dibinde ağlayan Aziz Yuhanna', 'Son Yargı gününde günahkarları tartan Başmelek Mikail', 'İmparator I. Basileios ve ailesinin taç giyme töreni'], '867 tarihli Ayasofya apsis mozaiği, İkonoklazm sonrası zaferin simgesi olarak Tanrı Doğuran (Theotokos) Meryem ve kucağındaki Çocuk İsa\'yı altın zemin önünde görkemli bir tahtta gösterir.'),
  ('Orta Bizans (Makedonya ve Komnenos hanedanları) dönemi kilise mimarisinde bazilika planının yerini alarak standartlaşan ve sembolik bir "mikrokozmos" yaratan yapı planı hangisidir?', 'Kapalı Yunan Haçı planı', ['Uzunlamasına beş nefli transeptli bazilika planı', 'Üstü açık peristil avlulu tapınak planı', 'Sekizgen dehlizli vaftizhane planı'], '9. yüzyıldan itibaren yaygınlaşan dört sütunlu/payeli Kapalı Yunan Haçı planlı kiliseler, merkez kubbeden alt duvarlara inen hiyerarşik mozaik programına en uygun mekanı sunmuştur.'),
  ('Bizans ikona ve mozaik sanatında Meryem Ana tasvirlerinin temel tiplerinden olan "Hodegetria" ile "Eleusa" arasındaki belirgin duygusal ve biçimsel fark nedir?', 'Hodegetria\'da Meryem kucağındaki İsa\'yı eliyle işaret ederek yol gösterirken, Eleusa\'da Çocuk İsa annesinin yanağına yüzünü yaslayarak şefkat bağı kurar', ['Hodegetria\'da Meryem tek başına kollarını açarak dua ederken, Eleusa\'da kucağında çarmıhtan indirilmiş yetişkin İsa\'yı tutar', 'Hodegetria yalnızca mermer heykel olarak yontulurken, Eleusa yalnızca el yazması kitap kapaklarında işlenir', 'Hodegetria tipinde Meryem tahtta otururken, Eleusa tipinde Meryem kanatlı bir melek görünümünde gökyüzünde uçar'], 'Hodegetria "Yol Gösteren" demektir ve ciddi, mesafeli bir duruşa sahiptir; Eleusa (Glikofilusa) ise anne ile çocuk arasındaki sıcak yanak yanağa teması vurgulayan "Şefkatli Meryem" tipidir.'),
  ('Bugün Moskova\'daki Tretyakov Galerisi\'nde korunan, 12. yüzyıl başlarında Konstantinopolis\'te yapılıp Rusya\'ya gönderilen ve Eleusa (Şefkatli Meryem) tipinin en ünlü başyapıtı sayılan ikona hangisidir?', 'Vladimir Meryemi İkonası', ['Sina Pantokrator İkonası', 'Kariye Deesis Mozaiği', 'Ravenna Theodora Panosu'], 'Komnenos dönemi Konstantinopolis atölyelerinde üretilen Vladimir Meryemi, Çocuk İsa\'nın annesinin boynuna sarıldığı ve Meryem\'in hüzünlü gözlerle oğlunun gelecekteki çilesini sezdiği eşsiz bir ikonadır.'),
  ('Ayasofya\'nın güneybatı giriş holü (vestibül) kapısı üzerindeki 10. yüzyıl mozaiğinde, ortadaki Meryem ve Çocuk İsa\'ya kentin surlarını ve Ayasofya\'nın maketini sunan iki büyük imparator kimlerdir?', 'Büyük Konstantin (kenti sunan) ve I. Justinianus', ['I. Theodosius ve oğlu Arkadios', 'III. Leon ve oğlu V. Konstantinos', 'II. Basileios ve kardeşi VIII. Konstantinos'], 'Bu ünlü sunu mozaiğinde sağdaki Konstantin kurduğu Konstantinopolis kent maketini, soldaki Justinianus ise inşa ettirdiği Ayasofya maketini kentin koruyucusu Meryem Ana\'ya armağan eder.'),
  ('Ayasofya\'nın güney galerisinde bulunan 12. yüzyıl başı tarihli "Komnenoslar Mozaiği"nde, Meryem ve Çocuk İsa\'nın iki yanında bağış kesesi ve ferman rulosu tutarak duran imparatorluk çifti kimdir?', 'II. İoannes Komnenos ve Macar asıllı eşi İmparatoriçe İrene', ['I. Justinianus ve eşi İmparatoriçe Theodora', 'VI. Leon ve dördüncü eşi Zoe Karbonopsina', 'XI. Konstantinos ve eşi Katerina Gattilusio'], '1118 civarına tarihlenen mozaikte II. İoannes Komnenos ile kızıl saç örgüleri ve pembe yanaklarıyla dikkat çeken Macar prensesi eşi Azize İrene (Piroska) kiliseye bağış sunarken görülür.'),
  ('İstanbul Edirnekapı\'da yer alan ve 14. yüzyıl başlarında devlet adamı Theodoros Metokhites tarafından baştan sona eşsiz mozaik ve fresklerle donatılan Geç Bizans dönemi başyapıtı yapı hangisidir?', 'Kariye', ['Fethiye (Pammakaristos) Sarnıcı', 'Zeyrek (Pantokrator) Medresesi', 'Tekfur Sarayı Şapeli'], 'Khora (Kariye), 1315-1321 yılları arasında Hazine Başvekili ve alim Theodoros Metokhites\'in baniliğinde Paleologos Rönesansı\'nın en zengin mozaik ve fresk döngüsüyle süslenmiştir.'),
  ('Kariye (Khora) Kilisesi\'nin iç narteks kapısı üzerindeki sunu mozaiğinde, başında görkemli doğu tarzı beyaz sarığı/kavuğuyla diz çökerek İsa\'ya kilisenin maketini sunan kişi kimdir?', 'Theodoros Metokhites', ['İmparator II. Andronikos', 'Patrik I. Athanasios', 'Mihail Psellos'], 'Kariye\'nin banisi Theodoros Metokhites, saraydaki "Megas Logothetes" unvanına özgü yüksek dilimli başlığı ve süslü kaftanıyla "Yaşayanların Ülkesi" (Khora ton Zonton) İsa\'ya yenilediği kiliseyi sunar.'),
  ('Bizans ikona ressamlığında ahşap panel üzerine bez yapıştırılıp alçı-tutkal karışımı astar (gesso/levkas) çekildikten sonra uzun yüzyıllar boyunca kullanılan temel boyama tekniği nedir?', 'Yumurta sarısı emülsiyonu ile hazırlanan tempera tekniği', ['Keten yağı ve terebentinle inceltilen yağlı boya tekniği', 'Islak kireç harcı üzerine uygulanan fresk tekniği', 'Su ve arap zamkı ile şeffaf sürülen sulu boya tekniği'], '6.-7. yüzyıllardan sonra sıcak balmumu (enkostik) tekniğinin yerini, doğal toprak ve mineral pigmentlerin yumurta sarısıyla bağlandığı dayanıklı yumurta temperası almıştır.'),
  ('Yunanistan\'daki Hosios Lukas ve Daphni manastırları ile Sakız Adası\'ndaki Nea Moni Manastırı, Bizans mozaik sanatının hangi parlak dönemine (11. yüzyıl) ait anıtsal örneklerdir?', 'Orta Bizans Dönemi', ['Erken Hristiyan Katakomp Dönemi', 'İkonoklazm Yasakları Dönemi', 'İmparator Justinianus\'un İlk İnşa Dönemi'], '11. yüzyılda inşa edilen Hosios Lukas, Nea Moni ve Daphni kiliseleri, Orta Bizans klasik mozaik üslubunun farklı duyarlılıklarını (ağırbaşlı manastır üslubundan klasik zarafete) günümüze taşıyan üç büyük anıttır.'),
  ('Eski Mısır ikonografisinde çömlekçi çarkında insanları ve onların ruh eşi "Ka"larını Nil çamurundan biçimlendirirken gösterilen koç başlı yaratıcı tanrı kimdir?', 'Khnum', ['Osiris', 'Seth', 'Anubis'], 'Elefantin Adası\'nın koruyucu tanrısı olan kıvrık boynuzlu koç başlı Khnum, tapınak kabartmalarında firavunun bedenini çömlekçi çarkında yoğururken betimlenir.'),
  ('Mısır mezar duvarlarındaki tarım sahnelerinde buğday biçen, üzüm ezen ve sığır güden köylülerin ayrıntılı biçimde resmedilmesinin öteki dünya inancındaki karşılığı nedir?', 'Mezar sahibinin sonsuz yaşamda (Aaru Tarlaları\'nda) açlık çekmemesi için büyüsel olarak kesintisiz gıda üretimi sağlamak', ['Firavun vergi memurlarına o yılki hasat miktarını kanıtlayan resimli muhasebe defteri bırakmak', 'Köylülerin sendikal haklarını savunmak amacıyla çalışma koşullarının zorluğunu belgelemek', 'Mezara giren ziyaretçilere çiftçilik mesleğini öğreten görsel bir ders kitabı hazırlamak'], 'Mısır\'da mezar resmi büyüsel gerçeklik taşır; duvardaki ekmek, bira ve hasat sahneleri "Ağız Açma" ve sunu dualarıyla öteki dünyada mezar sahibini ebediyen besler.'),
  ('Firavunun hükümdarlığının otuzuncu yılında fiziksel ve ilahi gücünü yenilemek amacıyla tören avlusunda koşu yaptığı ve Sakkara Zoser Külliyesi\'nde taş maket yapıları bulunan bayram hangisidir?', 'Heb-Sed (Jübile) Festivali', ['Yeni Yıl Taşkın Şenliği', 'İsis Gizem Töreni', 'Panathenaia Alayı'], 'Zoser Basamaklı Piramidi\'nin avlusundaki içi dolu sahte şapeller, firavunun öteki dünyada da Heb-Sed (iktidar yenileme) törenini sonsuza dek kutlaması için taştan yapılmıştır.'),
  ('Ur Kral Mezarlığı\'nda bulunan ve altın varak, lacivert taş ile sedef kaplı şaha kalkmış bir keçiyi çiçekli çalıya ön ayaklarını dayamış hâlde gösteren ünlü Sümer heykeli hangisidir?', 'Çalıdaki Koç', ['Altın Buzağı', 'Babil Aslanı', 'Troya Atı'], 'British Museum ve Penn Museum\'da birer eşi bulunan "Çalıdaki Koç" (Ram in a Thicket), Sümer kuyumculuk, ahşap çekirdek üzerine altın ve lapis lazuli kakma sanatının başyapıtıdır.'),
  ('Bir arkeoloji öğrencisi incelediği Babil eserinde mavi sırlı tuğlalar üzerinde uzun boyunlu, çatallı dilli, ön ayakları aslan, arka ayakları kartal pençeli pullu bir yaratık görüyorsa bunu hangi tanrıyla eşleştirmelidir?', 'Babil\'in baş tanrısı Marduk ile', ['Sümer\'in ay tanrısı Nanna ile', 'Mısır\'ın güneş tanrısı Ra ile', 'Hitit\'in fırtına tanrısı Teşup ile'], 'İştar Kapısı\'ndaki Muşhuşşu (kızgın yılan-ejderha) figürü, Babil panteonunun zirvesindeki Tanrı Marduk\'un kutsal simgesidir.'),
  ('Asur saray kabartmalarında savaş, av ve kuşatma sahnelerinde derinlik (uzaklık) etkisi vermek isteyen sanatçılar çizgisel perspektif yerine hangi görsel yöntemi kullanmıştır?', 'Uzaktaki figürleri kağıdın/taşın daha üst kısmına yerleştirmeyi ve yan yana bindirmeyi', ['Uzaktaki askerleri nokta kadar küçültüp ufuk çizgisinde birleştirmeyi', 'Arka plandaki dağları mavi puslu fırça darbeleriyle bulanıklaştırmayı', 'Yalnızca öndeki figürleri yontup arkadakileri tamamen görünmez bırakmayı'], 'Hem Mezopotamya hem Mısır kabartmalarında mekânsal geriye gidiş (uzaklık), figürlerin boyunu küçültmeden onları kompozisyon yüzeyinde daha yukarıya dizmekle (dikey perspektif) sağlanmıştır.'),
  ('Osmaniye Kadirli\'deki Geç Hitit kalesi "Karatepe-Aslantaş"ta bazalt ortostat kabartmalarının yanı sıra Hitit (Luvi) hiyerogliflerinin tam olarak çözülmesini sağlayan hangi çift dilli yazıt bulunmuştur?', 'Fenikece ve Luvi Hiyeroglifli Karatepe Çift Dilli Yazıtı', ['Yunanca ve Demotik yazılı Rosetta Taşı', 'Persçe ve Elamca yazılı Behistun Kaya Anıtı', 'Latince ve Yunanca yazılı Ankara Anıtı'], 'Halet Çambel ve Helmuth Theodor Bossert\'in çalışmalarıyla korunan Karatepe-Aslantaş\'taki Fenikece-Hiyeroglif çift dilli (bilingual) ortostatlar, Anadolu hiyerogliflerinin çözülmesinde anahtar olmuştur.'),
  ('Mısır\'da keten kumaş veya eski papirüs katmanlarının alçı ve zamkla sertleştirilip kalıplanmasıyla mumya maskesi ve tabut kılıfı yapımında kullanılan hafif malzemeye ne ad verilir?', 'Kartonaj (Cartonnage)', ['Terakota (Pişmiş toprak)', 'Stuko (Mermer tozu sıva)', 'Majolika (Kalay sırlı seramik)'], 'Altın maske yaptıramayan soylular ve rahipler için keten/papirüs ve alçıdan üretilen "kartonaj" maskeler, canlı renkler ve altın varakla boyanarak mumya başına geçirilirdi.'),
  ('Eski Mısır tapınak duvarlarında ve mezarlarında yarım kalmış kabartmaların incelenmesi sonucunda iş bölümünün nasıl yürüdüğü anlaşılmıştır?', 'Önce kareli oran ağı çekilip kırmızı çizgiyle taslak yapıldığı, usta çizerin siyahla düzelttiği, heykeltıraşın yonttuğu ve en son boyacıların renklendirdiği', ['Tek bir dahi sanatçının iskele kurarak on yıl boyunca kimseye dokundurmadan tüm duvarı tek başına bitirdiği', 'Kabartmaların önce boyanıp kuruduktan sonra boyaların üzerinden çekiçle kırılarak yontulduğu', 'Taş blokların ocaktan çıkarılmadan önce dağın içinde karanlıkta ezbere boyandığı'], 'Teb mezarlarında (örneğin Horemheb\'in Krallar Vadisi\'ndeki yarım kalan mezarı KV57) bu aşamalı ekip çalışmasının tüm katmanları yan yana açıkça görülür.'),
  ('Anadolu\'da Hitit sanatında tanrıların başlıklarındaki sivri külahların ön yüzüne işlenen "boynuz" dizileri hangi komşu bölgenin ikonografik geleneğiyle doğrudan ilişkilidir?', 'Mezopotamya (Sümer-Akad-Babil-Asur) tanrı başlığı geleneğiyle', ['Klasik Yunanistan\'daki zeytin dalı çelengi geleneğiyle', 'Eski Çin\'deki yeşim taşı ejderha tokası geleneğiyle', 'Roma İmparatorluğu\'ndaki defne yapraklı Sezar tacıyla'], 'Yazılıkaya\'daki Teşup ve diğer tanrıların sivri külahlarında görülen üst üste boynuzlar (ilahilik derecesi göstergesi), Mezopotamya\'dan Anadolu Hitit sanatına geçen köklü bir semboldür.'),
  ('Roma İmparatoru Caracalla\'ya ait mermer portre büstlerinde başın sertçe yana çevrilmesi, çatık kaşlar ve kısa kesilmiş asker saçı-sakalı hangi imajı yansıtmak amacıyla işlenmiştir?', 'Orduyla özdeşleşen tavizsiz, enerjik ve korku uyandıran askeri hükümdar imajını', ['Stoacı felsefeye kendini adamış barışsever ve dalgın bilge imajını', 'Klasik Yunan gençlik tanrısı Apollon\'un durgun ve kadınsı zarafetini', 'Senatoya koşulsuz itaat eden mütevazı sivil memur kimliğini'], 'Severuslar hanedanından Caracalla\'nın büstleri, çatılmış alnındaki X biçimli kırışıklık ve delici bakışlarıyla Roma\'da "askeri imparatorlar" çağı portreciliğinin prototipini oluşturmuştur.'),
  ('Roma\'daki Forum Romanum\'un kuzeybatı girişinde yer alan, MS 203 yılında Partlara karşı kazanılan zaferler anısına dikilmiş üç gözlü anıtsal mermer zafer takı hangisidir?', 'Septimius Severus Zafer Takı', ['Titus Zafer Takı', 'Drusus Zafer Takı', 'Gallienus Kemeri'], 'Üç kemerli geçişe sahip Septimius Severus Zafer Takı, imparator ve oğulları Caracalla ile Geta\'nın doğu seferlerini anlatan kalabalık panolarla süslüdür.'),
  ('Roma\'da MS 112 yılında Şamlı Apollodoros tarafından tasarlanan ve Traianus Sütunu\'nu iki yanındaki Yunanca ve Latince kütüphanelerin ortasında barındıran devasa kompleks hangisidir?', 'Traianus Forumu ve Basilica Ulpia', ['Augustus Mozolesi Kompleksi', 'Diocletianus Sarayı', 'Hadrianus Villası'], 'İmparatorluk forumlarının en büyüğü olan Traianus Forumu\'nda kütüphanelerin üst teraslarından Traianus Sütunu\'nun üst kabartmaları yakından izlenebiliyordu.'),
  ('Pompei\'de Livia Villası (Prima Porta) yemek odasını çepeçevre saran ve izleyiciye serin bir meyve bahçesinin ortasındaymış hissi veren ünlü duvar resmi hangi resim türünün antik öncüsüdür?', 'Hava perspektifini kullanan kesintisiz manzara (peyzaj) resminin', ['Geometrik soyutlama yapan kübist natürmort anlayışının', 'Siyasi karikatür ve toplumsal hiciv gravürlerinin', 'Altın varak zeminli tek figürlü aziz ikonalarının'], 'Livia Villası\'nın bahçe freskleri; ön plandaki net nar ağaçları ve kuşlardan arkadaki puslu ağaçlara doğru yumuşayan atmosferik perspektifiyle antik manzara sanatının zirvesidir.'),
  ('Pompei\'de bulunan ve elinde balmumu yazı tableti (tabula) ile kalemiyle (stylus) düşünceli biçimde bakan genç kadını ve yanındaki eşini betimleyen ünlü duvar portresi yaygın olarak hangi adla tanınır?', 'Terentius Neo ve Eşi (Fırıncı ve Eşi) Portresi', ['İmparator Vespasianus ve Kızı Portresi', 'Antonius ve Kleopatra Düğün Freski', 'Orpheus ve Eurydike Ayrılık Sahnesi'], 'Napoli Ulusal Arkeoloji Müzesi\'ndeki bu Pompei freski, orta sınıf bir Romalı çiftin okuryazar ve kültürlü görünme arzusunu doğal yüz ifadeleriyle yansıtır.'),
  ('Erken Hristiyan sanatında 4. yüzyıldan itibaren lahitlerde ve apsis mozaiklerinde görülen, tahtta veya gök kubbe üzerinde oturan İsa\'nın Aziz Petrus\'a bir yasa rulosu verdiği sahneye ne ad verilir?', 'Traditio Legis (Yasanın / Yeni Ahit\'in Teslimi)', ['Deesis (Son Yargı Yakarışı)', 'Anastasis (Cehennem Kapılarının Kırılışı)', 'Hetoimasia (Boş Tahtın Hazırlanışı)'], 'Roma imparatorlarının valilere yetki fermanı vermesi ikonografisinden uyarlanan Traditio Legis, İsa\'nın Aziz Petrus ve Pavlus huzurunda yeni ilahi yasayı kiliseye emanet etmesini simgeler.'),
  ('Roma\'da MS 432-440 yıllarında Papa III. Sixtus tarafından yaptırılan ve orta nef kemerleri ile zafer takı üzerinde Eski ve Yeni Ahit sahnelerini içeren erken dönem mozaiklerini koruyan büyük bazilika hangisidir?', 'Santa Maria Maggiore Bazilikası', ['Eski Aziz Petrus Bazilikası', 'San Clemente Kilisesi', 'Aziz Pavlus Surlar Dışında Bazilikası'], 'Meryem\'e "Theotokos" (Tanrı Doğuran) unvanı veren 431 Efes Konsili\'nin hemen ardından süslenen Santa Maria Maggiore, Roma\'daki en iyi korunmuş 5. yüzyıl bazilikası ve mozaik dizisidir.'),
  ('Ravenna\'da Ostrogot Kralı Theoderik\'in MS 520 civarında kendisi için yaptırdığı iki katlı, ongen planlı anıt mezarın üstünü örten kubbenin mimari açıdan en sıra dışı özelliği nedir?', 'Tuğla veya betonla örülmeyip yaklaşık üç yüz ton ağırlığındaki tek parça (monolit) İstirya kireçtaşından yontularak yerine oturtulmuş olması', ['Tamamen şeffaf renkli cam bloklardan yapılarak güneş ışığını prizma gibi kırması', 'Ahşap kütüklerin çivisiz geçme tekniğiyle kırlangıç örtü şeklinde üst üste dizilmesi', 'Pantheon gibi ortasında dokuz metrelik açık bir oculus boşluğu barındırması'], 'Theoderik Mozolesi\'nin çatısı, deniz yoluyla İstirya\'dan getirilen yaklaşık 11 metre çapındaki yekpare dev bir taş bloğun oyulmasıyla oluşturulmuş benzersiz bir monolit kubbedir.'),
  ('Bizans\'ta 6. yüzyılda saray ve kilise için üretilen, İmparator Justinianus\'u şaha kalkmış atı üzerinde muzaffer komutan, altında toprak bereketini ve üstte İsa büstünü gösteren Louvre Müzesi\'ndeki ünlü fildişi levha hangisidir?', 'Barberini Fildişi', ['Harbaville Triptikosu', 'Maximianus Fildişi Tahtı', 'Veroli Fildişi Kutusu'], 'Beş parçalı fildişi panodan oluşan Barberini Fildişi, yüksek kabartma tekniğiyle atlı imparatoru (muhtemelen Justinianus) hem askeri fatih hem de İsa\'nın kutsadığı hükümdar olarak betimler.'),
  ('6. yüzyıl Erken Bizans kitap sanatının (minyatür) en görkemli örneklerinden olan "Viyana Genesis", "Rossano İncili" ve "Sinop İncili" yazmalarında parşömen sayfalarının ortak lüks özelliği nedir?', 'Parşömenlerin imparatorluk rengi olan erguvan (mor) boyayla renklendirilip metinlerin gümüş ve altın mürekkeple yazılmış olması', ['Sayfaların Mısır\'dan getirilen kaba papirüs şeritlerine kömür kalemiyle çizilmiş olması', 'Kağıt hamuruna ipek lifleri karıştırılarak yalnızca siyah-beyaz baskı kalıplarıyla çoğaltılması', 'Resimlerin parşömen üzerine değil doğrudan fildişi sayfalar üzerine kazınarak işlenmesi'], 'Erguvan (murex deniz kabuğundan elde edilen mor boya) Bizans\'ta yalnızca imparatorluk ailesine özgüydü; bu lüks el yazmaları saray atölyeleriyle bağlantılı olarak mor parşömene gümüş mürekkeple (codex purpureus) yazılmıştır.'),
  ('Bizans\'ta 754 yılında İmparator V. Konstantinos tarafından toplanan ve ikonaların üretilmesini resmen aforoz sebebi sayan İkonoklast (tasvir karşıtı) konsil nerede toplanmıştır?', 'Hieria Sarayı Konsili', ['Birinci İznik Konsili', 'Kalkedon (Kadıköy) Dördüncü Konsili', 'Efes Üçüncü Ekümenik Konsili'], '754 Hieria Konsili, İkonoklast teolojinin zirvesidir; İsa\'yı resmetmenin ya onun ilahiliğini maddeye hapsetmek (Monofizitlik) ya da iki doğasını bölmek (Nasturilik) anlamına geleceğini ileri sürmüştür.'),
  ('İkonoklazm\'ın 843\'te sona ermesinin ardından I. Basileios ile başlayıp 11. yüzyıl ortasına kadar süren, Bizans el yazmalarında ve fildişi oymacılığında Antik Klasik Yunan formlarının yeniden canlandığı döneme ne ad verilir?', 'Makedonya Rönesansı', ['Paleologos Rönesansı', 'Justinianus Restorasyonu', 'karanlık Yüzyıllar Dönemi'], 'Makedonya Hanedanı döneminde (867-1056) Paris Psalteri gibi el yazmalarında ve Veroli Kutusu gibi fildişilerde antik kişileştirmeler, yumuşak beden modellemeleri ve klasik derinlik yeniden canlanmıştır.'),
  ('Makedonya Rönesansı döneminde (10. yüzyıl) üretilen üç kanatlı ünlü "Harbaville Triptikosu" (Louvre) gibi küçük boyutlu fildişi ikonaların temel kullanım amacı neydi?', 'Soylu ve varlıklı Bizanslıların evlerinde veya seyahatlerinde yanlarında taşıyarak özel ibadet (kişisel dindarlık) yapmalarını sağlamak', ['Kilisenin dış cephe duvarlarına harçla gömülerek yağmurdan koruyucu tılsım oluşturmak', 'Yalnızca ölen piskoposların lahitlerinin içine konulup bir daha hiç açılmamak üzere gömülmek', 'Okuma yazma öğrenen çocukların üzerinde demir kalemle yazı alıştırması yapmasını sağlamak'], 'Kanatları katlanıp kapanabilen fildişi triptikler (üçlü panolar), ortada Deesis ve çevresinde koruyucu aziz kabartmalarıyla kişisel ibadet için üretilmiş taşınabilir lüks ikonalardır.'),
  ('Venedik\'teki San Marco Bazilikası\'nın yüksek sunağında bulunan, yüzlerce Bizans mine (cloisonné) plakası, altın ve değerli taşlarla süslü ünlü sunak panosunun adı nedir?', 'Pala d\'Oro (Altın Pano)', ['Ara Pacis (Barış Sunağı)', 'Gemma Augustea (Augustus Taşı)', 'Tabula Peutingeriana'], 'İlk kez 10. yüzyılda Konstantinopolis\'ten sipariş edilen ve 1204 Dördüncü Haçlı Seferi yağmasından getirilen Bizans mineleriyle zenginleştirilen Pala d\'Oro, Bizans kuyumculuk sanatının en görkemli topluluğudur.'),
  ('Sicilya\'da Norman kralları döneminde (12. yüzyıl) Bizanslı mozaik ustalarının davet edilmesiyle süslenen ve apsis yarım kubbelerindeki devasa Pantokrator İsa mozaikleriyle tanınan iki büyük katedral hangileridir?', 'Cefalù Katedrali ve Monreale Katedrali', ['Milano Katedrali ve Pisa Katedrali', 'Siena Katedrali ve Orvieto Katedrali', 'Notre-Dame ve Chartres Katedrali'], 'Norman kralları II. Ruggero ve II. Guglielmo, Sicilya\'daki Cefalù, Monreale katedralleri ile Palermo\'daki Cappella Palatina\'yı Konstantinopolis\'ten gelen Bizans mozaikçilerine kaplatmıştır.'),
  ('Makedonya\'nın Üsküp kenti yakınlarındaki "Nerezi Aziz Panteleimon Kilisesi"nde bulunan ve 1164 yılına tarihlenen ünlü duvar freskleri, hangi sahnesindeki yoğun insani acı anlatımıyla Erken Rönesans ressamı Giotto\'nun habercisi sayılır?', 'İsa\'ya Ağıt (Threnos / Lamentation) sahnesinde Meryem\'in ölü oğlunu kucağına alıp yanağını yanağına bastırarak hıçkırıkla ağlamasıyla', ['Pantokrator İsa\'nın gökyüzünde altın bir tahtta hiç kıpırdamadan sertçe ileriye bakmasıyla', 'İmparator I. Manuel Komnenos\'un savaş meydanında düşmanlarını mızrakla devirmesiyle', 'On İki Havari\'nin simetrik sütunlar arasında ellerinde rulolarla tek sıra dizilmesiyle'], 'Komnenos dönemi eseri olan Nerezi fresklerindeki Ağıt sahnesi, Meryem\'in derin kederle çatılmış kaşları ve ölü İsa\'ya sarılışıyla Bizans sanatında duygusal dışavurumun (pathos) zirvelerinden biridir.'),
  ('Dört İncil yazarını (Matta, Markos, Luka, Yuhanna) temsil eden kanatlı insan/melek, aslan, boğa ve kartal sembollerinin bir arada kullanıldığı Erken Hristiyan ve Bizans ikonografisine ne ad verilir?', 'Tetramorf', ['İkhthys', 'Orans', 'Kriophoros'], 'Hezekiel ve Vahiy kitaplarına dayanan Tetramorf simgeciliğinde; Matta insan/melek, Markos kanatlı aslan, Luka kanatlı boğa, Yuhanna ise kartal ile sembolize edilir.'),
  ('Erken Hristiyan ve Bizans sanatında İsa\'nın veya Khi-Rho monogramının iki yanına Yunan alfabesinin ilk ve son harfleri olan "Alfa (Α)" ile "Omega (Ω)" yazılmasının teolojik anlamı nedir?', 'İsa Mesih\'in başlangıç ve son olduğunu, zamanın ve evrenin mutlak hakimi bulunduğunu simgelemek', ['Eserin hangi imparatorun saltanatının kaçıncı yılında tamamlandığını tarihlemek', 'Mozaik ustasının adını ve bağlı olduğu loncanın baş harflerini gizlice imzalamak', 'Okuma yazma bilmeyen cemaate Yunan alfabesini görsel olarak öğretmek'], 'Vahiy Kitabı\'ndaki "Ben Alfa ve Omega\'yım, ilk ve sonum" ayetine dayanan bu harfler, Mesih\'in ezeliliğini ve ebediliğini ifade eder.'),
  ('Selanik\'te İmparator Galerius tarafından 4. yüzyıl başında anıt mezar veya tapınak olarak inşa edilen, daha sonra kiliseye çevrilip kubbesi anıtsal aziz ve mimari cephe mozaikleriyle kaplanan dairesel Roma yapısı hangisidir?', 'Selanik Rotondası', ['Aziz Demetrios Bazilikası', 'Hosios David Şapeli', 'Kutsal Havariler Kilisesi'], 'Kalın tuğla duvarlı dairesel Roma yapısı olan Selanik Rotondası, Hristiyanlığa uyarlandığında kubbesi altın fon önünde ışıltılı mimari sahneler ve orans pozundaki şehit aziz mozaikleriyle bezenmiştir.'),
  ('Trabzon\'da 13. yüzyıl ortasında Trabzon İmparatoru I. Manuel Komnenos tarafından yaptırılan ve Geç Bizans dönemi taş kabartmaları ile zengin duvar fresklerini barındıran önemli anıt hangisidir?', 'Trabzon Ayasofya Kilisesi', ['Sümela kaya şapeli', 'İznik Ayasofya Bazilikası', 'Efes Aziz Yuhanna Bazilikası'], 'Trabzon Ayasofya\'sı; güney cephesindeki Yaratılış ve Adem-Havva taş kabartma frizi (Gürcü-Selçuklu-Bizans etkileşimli) ve iç mekandaki Paleologos üsluplu freskleriyle benzersizdir.'),
  ('Yerebatan Sarnıcı\'nın kuzeybatı köşesindeki iki sütunun altında yer alan antik Roma dönemi dev "Medusa Başları"nın biri yan, diğeri baş aşağı (ters) yerleştirilmiştir; bu durumun en akla yatkın mimari açıklaması nedir?', 'Devşirme taş blokların yalnızca sütun boyunu dengelemek için uygun yükseklikte birer kaide (altlık) olarak pragmatik biçimde kullanılmış olması', ['Bizanslı mühendislerin suyun akış yönünü Medusa\'nın saç kıvrımlarına göre hesaplamış olması', 'İkonoklazm döneminde sarnıcın suyunun boşaltılıp heykellerin cezalandırma amacıyla ters çevrilmesi', 'Ters duran Medusa\'nın tatlı suyu, yan duran Medusa\'nın ise deniz suyunu simgelemesi'], 'Spolia kullanımında Hristiyan ustalar pagan mitolojik kabartmaları hem görsel etkisizleştirmek hem de ağırlığı en sağlam taşıyacak düz yüzeyi elde etmek için yan veya ters yatırmışlardır.'),
  ('İstanbul\'da Saraçhane\'de yer alan ve 524-527 yıllarında soylu Anicia Juliana tarafından Süleyman Tapınağı\'nı geride bırakma iddiasıyla yaptırılan, kazılarda çok zengin oyma mermer mimari parçaları bulunan kilise hangisidir?', 'Aziz Polyeuktos Kilisesi', ['khora Manastırı', 'Pammakaristos Kilisesi', 'Mirelaion Kilisesi'], 'Ayasofya\'dan hemen önce inşa edilen Aziz Polyeuktos Kilisesi, Sasani etkili bitkisel bezemeleri, tavus kuşlu nişleri ve bugün Venedik San Marco önünde duran "Pilastri Acritani" sütunlarıyla ünlüdür.'),
  ('Roma\'da İmparator Caracalla ve Diocletianus tarafından halk için inşa edilen devasa "Hamam Kompleksleri" (Thermae) içinde sıcak, ılık ve soğuk yıkanma salonlarına sırasıyla hangi Latince adlar verilirdi?', 'Caldarium (sıcak), Tepidarium (ılık), Frigidarium', ['Atrium, Tablinum, Peristil', 'Narteks, Naos, Bema', 'Cavea, Orchestra, Scaenae frons'], 'Roma imparatorluk hamamları kütüphane ve spor alanları içeren dev kültür merkezleriydi; çapraz tonozlu görkemli Frigidarium salonları sonradan büyük bazilikaları etkilemiştir.'),
  ('Roma\'da ölü yakma (kremasyon) geleneğinden gömme (inhumasyon) geleneğine geçilen MS 2. ve 3. yüzyıllarda heykeltıraşlık atölyelerinin en yoğun ürettiği kabartmalı mezar anıtı türü hangisidir?', 'Mermer lahitler', ['Yer altı katakomp freskleri', 'Balmumu mumya maskeleri', 'Tunç zafer sütunları'], 'Hadrianus ve Antoninler döneminden itibaren ölü gömme adeti yaygınlaşınca mitolojik sahneler, savaşlar (Ludovisi Lahdi gibi) ve ardından Hristiyan konuları içeren mermer lahit üretimi patlama yapmıştır.'),
  ('Roma taban mozaiklerinde ziyafet salonunun zeminine düşmüş balık kılçıkları, tavuk kemikleri, meyve kabukları ve bunları kemiren küçük bir fare yanılsamasını işleyen Helenistik kökenli esprili mozaik türüne ne ad verilir?', 'Asarotos oikos (Süpürülmemiş oda mozaiği)', ['Opus sectile (Kesme mermer döşeme)', 'Emblema (Merkez madalyon resmi)', 'İnkrüstasyon (Duvar mermer taklidi)'], 'Bergamalı Sosos\'un icat ettiği ve Roma\'da (örneğin Vatikan Müzeleri\'ndeki Herakleitos imzalı mozaik) çok sevilen "süpürülmemiş zemin", yemek artıklarının gölgelerini bile işleyen bir trompe-l\'oeil (göz aldatmacası) türüdür.'),
  ('Ayasofya\'nın ana mekan (naos) zemininde sağ tarafta yer alan, porfir, yeşil teselya taşı ve renkli mermer dairelerin iç içe geçtiği "Omphalion" (Dünyanın Göbeği) döşemesinin Bizans törenlerindeki işlevi neydi?', 'Bizans imparatorlarının taç giyme törenlerinde (koronasyon) imparatorluk tahtının ve kutsama ritüelinin konumlandığı kutsal merkez nokta olması', ['Kiliseye gelen yabancı elçilerin silahlarını bıraktığı güvenlik sınırı olması', 'Yalnızca koro şefinin durarak kubbedeki ses yankısını kontrol ettiği akustik nokta olması', 'Güneş saatine göre öğle vaktinin kubbe penceresinden düşen ışıkla ölçüldüğü takvim halkası olması'], 'Opus sectile tekniğindeki dairesel Omphalion panosu, yeryüzünün merkezini simgeler ve Bizans imparatorlarının patrik tarafından taçlandırıldığı ayinin odak alanını oluştururdu.'),
  ('Rusya, Balkanlar ve Anadolu\'da Bizans sanat mirasını sürdüren 14. yüzyıl sonu - 15. yüzyıl başı ikona ressamlığının en büyük iki ustası kimlerdir?', 'Yunan asıllı Theophanes (Feofan Grek) ve Rus keşiş Andrey Rublev', ['Trallesli Anthemios ve Miletoslu İsidoros', 'Cimabue ve öğrencisi Giotto di Bondone', 'Gentile Bellini ve kardeşi Giovanni Bellini'], 'Konstantinopolis\'ten Rusya\'ya giden dinamik dışavurumcu fresk ustası Theophanes (Feofan Grek) ile onun yanında yetişip "Eski Ahit Üçlüsü" ikonasını yapan lirik usta Andrey Rublev Ortodoks ikona sanatının zirvesidir.'),
  ('Erken Hristiyan bazilikalarının batısında, kiliseye girmeden önce cemaatin toplandığı ve ortasında genellikle arınma çeşmesi (kantharos/fiale) bulunan dört yanı revaklı açık avluya ne ad verilir?', 'Atrium', ['Pastoforyon', 'Synthronon', 'Parekklesion'], 'Roma ev mimarisinden alınan atrium, Eski Aziz Petrus Bazilikası ve erken dönem kiliselerinde dünyevi sokak ile kutsal iç mekan arasında geçiş sağlayan sütunlu ön avludur.'),
  ('Erken Hristiyan ve Bizans kiliselerinin apsis duvarı boyunca yarım daire şeklinde kademeli olarak yükselen ve ayin sırasında din adamlarının (ruhban sınıfının) oturduğu taş sıralara ne ad verilir?', 'Synthronon', ['İkonostasis', 'Ambon', 'Kiboryon'], 'Aya İrini Kilisesi\'nde çok iyi korunmuş bir örneği görülen synthronon, antik tiyatro oturma basamaklarını andıran, ortasında piskopos tahtının yer aldığı kademeli ruhban oturma düzenidir.'),
  ('Bizans kiliselerinde apsisin sağında ve solunda yer alan, ayin ekmeği ile şarabının hazırlandığı (Prothesis) ve kutsal kaplar ile giysilerin saklandığı (Diakonikon) bu iki yan odaya birlikte ne ad verilir?', 'Pastoforyon hücreleri', ['Narteks revakları', 'Triforyum galerileri', 'Katakomp nişleri'], 'Bema ve apsisin iki yanındaki servis odaları olan prothesis ve diakonikon, mimarlık terminolojisinde pastoforyon (pastophoria) olarak adlandırılır.'),
  ('Orta ve Geç Bizans kilise mimarisinde dış cephe duvarlarının yalnızca taş veya yalnızca tuğlayla değil, kesme taş sıraları ile kırmızı tuğla kuşaklarının dönüşümlü dizilmesiyle örülmesi (almaşık duvar) hangi estetik etkiyi sağlamıştır?', 'Erken dönemin sade ve ağır dış cephelerini çok renkli (polikrom), hareketli ve plastik bir cephe bezemesine dönüştürmüştür', ['Duvarların dışarıdan hiç görünmemesini sağlayarak yapıları doğada kamufle etmiştir', 'Sıva tutmayan kaygan bir yüzey yaratarak dış cephe fresklerinin yapılmasına zemin hazırlamıştır', 'Kubbelerin tamamen kaldırılıp düz damlı kerpiç yapılara geçilmesine neden olmuştur'], 'Özellikle Geç Bizans mimarisinde (Tekfur Sarayı, Kariye, Fethiye gibi) taş ve tuğlanın almaşık örgüsü, balıkksırtı, meander ve güneş motifli tuğla dizilimleriyle dış cepheyi adeta dokuma gibi süslemiştir.'),
  ('Bizans resim sanatında Başkalaşım (Metamorfoz) ve Diriliş (Anastasis) gibi sahnelerde yalnızca başı değil İsa\'nın tüm bedenini çepeçevre saran badem veya elips biçimli çok katmanlı ilahi ışık alanına ne ad verilir?', 'Mandorla', ['Clerestory ışık katı', 'Synthronon kademesi', 'Loros imparatorluk şalı'], 'İtalyancada badem anlamına gelen mandorla (Yunanca doxa), İsa\'nın ilahi şanının tüm bedeniyle tezahür ettiği anlarda mavi veya beyaz eşmerkezli ışık kuşakları olarak resmedilir.'),
  ('Bizans imparator ve imparatoriçelerinin tören mozaiklerinde (örneğin Zoe, Komnenoslar ve Konstantin-Justinianus panolarında) omuzlarından çapraz dolanıp öne sarkan değerli taşlarla işli uzun altın şeride ne ad verilir?', 'Loros', ['Toga praetexta', 'Khlamys pelerini', 'Stola elbisesi'], 'Antik Roma konsüllerinin giydiği trabea triumphalis giysisinden evrilen mücevherli ağır altın kuşak olan loros, Bizans imparatorlarının İsa\'nın yeryüzündeki temsilcisi olarak giydiği en görkemli tören kıyafetidir.'),
  ('Roma\'daki Piazza Navona meydanının bugün sahip olduğu uzun elips biçimli kentsel planı, tabanında kalıntıları bulunan hangi antik Roma spor yapısının formunu birebir korumasından kaynaklanır?', 'Domitianus Stadyumu', ['Circus Maximus', 'Caracalla Hamamı', 'Traianus Pazarı'], 'İmparator Domitianus\'un Yunan tarzı atletizm yarışları için MS 86\'da yaptırdığı stadyumun oturma kademeleri (cavea) üzerine Orta Çağ ve Barok binalar oturtulmuş, arena boşluğu ise Piazza Navona meydanı olarak kalmıştır.'),
  ('İmparator Nero\'nun MS 64\'teki Büyük Roma Yangını sonrasında kent merkezinde kendisi için yaptırdığı, döner yemek salonu ve "Fabullus" adlı ressamın grotesk tavan freskleriyle ünlü dev sarayın adı nedir?', 'Domus Aurea', ['Domus Flavia', 'Palazzo Vecchio', 'Villa Borghese'], 'Nero\'nun Altın Ev\'i (Domus Aurea), toprağın altında kalan tonozlu odaları 15. yüzyıl sonunda Rönesans sanatçıları (Rafael vb.) tarafından mağara (grotta) sanılarak keşfedilince "grotesk" süsleme üslubuna ilham vermiştir.'),
  ('Antalya\'nın Serik ilçesinde bulunan, İmparator Marcus Aurelius döneminde mimar Zenon tarafından tasarlanan ve sahne binası (scaenae frons) ile birlikte Akdeniz\'de en sağlam korunmuş Roma tiyatrosu hangisidir?', 'Aspendos Antik Tiyatrosu', ['Efes Büyük Tiyatrosu', 'Bergama Akropol Tiyatrosu', 'Miletos Antik Tiyatrosu'], 'Mimar Theodoros oğlu Zenon\'un MS 2. yüzyılda inşa ettiği Aspendos Tiyatrosu, iki katlı görkemli sahne binası ve üst galeri kemerleriyle Roma tiyatro mimarisinin dünyadaki en eksiksiz örneğidir.'),
  ('Gaziantep\'teki Zeugma ve Hatay (Antakya) Arkeoloji Müzesi\'nde sergilenen dünyaca ünlü "Çingene Kızı" veya "Okeanos ve Tethys" mozaikleri hangi dönem ve mekan kültürünün ürünleridir?', 'Roma İmparatorluğu döneminde (MS 2.-3. yüzyıl) doğu eyaletlerindeki varlıklı Roma villalarının ziyafet salonu ve sığ süs havuzu tabanlarının', ['İkonoklazm döneminde Bizans manastırlarının gizli ibadet mahzenlerinin', 'Erken Hristiyanlıkta vaftiz edilmemiş adayların beklediği bazilika avlularının', 'Klasik Yunan döneminde Atina Akropolü\'ndeki tapınak çatılarının'], 'Fırat kıyısındaki Zeugma ve Asi kıyısındaki Antiokheia (Antakya) kentlerindeki zengin Roma villaları, Helenistik mitoloji sahnelerini üç boyutlu gölgeleme tekniğiyle işleyen muazzam taban mozaikleriyle döşenmiştir.'),
  ('İstanbul Fatih\'te (Saraçhane yakınında) ayakta duran "Kıztaşı" adlı korint başlıklı granit anıt sütun, MS 5. yüzyıl ortasında hangi Doğu Roma (Bizans) imparatoru onuruna dikilmiştir?', 'İmparator Marcianus', ['İmparator Herakleios', 'İmparator I. Aleksios', 'İmparator Jül Sezar'], 'Kaidesinde kanatlı iki Zafer (Nike) kabartması ve Latince ithaf yazıtı bulunan Marcianus Sütunu (Kıztaşı), Konstantinopolis\'in 5. yüzyıl kentsel anıt sütunu geleneğinin günümüze sağlam ulaşmış örneğidir.'),
  ('1261\'de Konstantinopolis\'in Latinlerden geri alınmasından 1453\'e kadar süren son Bizans dönemi sanatı (Paleologos Rönesansı), devletin ekonomik ve askeri küçülmesine rağmen resim ve mozaikte nasıl bir karakter sergilemiştir?', 'Dev boyutlu yapılar yerine küçük ve zarif kiliselerde (Kariye, Fethiye, Mistra gibi) duygusal derinliği, renk zenginliği ve öyküleyici hareketliliği zirveye çıkan incelikli bir sanat yaratmıştır', ['Ekonomik darlık nedeniyle mozaik ve fresk yapımını tamamen bırakıp tüm kilise duvarlarını beyaza boyamıştır', 'Doğu Hristiyan geleneklerini tamamen terk ederek Gotik katedrallerin vitray ve heykel üslubunu birebir kopyalamıştır', 'Yalnızca askeri kale mimarisine yönelerek figüratif ressamlığı yasaklamıştır'], 'Paleologos döneminde devlet küçülüp yoksullaşırken entelektüel ve sanatsal yaratıcılık tam tersine parlamış; İstanbul, Selanik ve Mora\'daki Mistra kiliselerinde zarif ve insani bir resim üslubu doğmuştur.'),
  ('Roma\'da İmparator Traianus döneminde Şamlı Apollodoros tarafından Quirinalis Tepesi\'nin yamacı tıraşlanarak yarım daire kademeler halinde inşa edilen, yüz elliden fazla dükkan ve idari ofis barındıran çok katlı tuğla-beton yapı hangisidir?', 'Traianus Pazarı', ['Kolezyum Amfitiyatrosu', 'Maxentius Bazilikası', 'Ara Pacis Sunağı'], 'Traianus Forumu\'nun hemen arkasında yükselen çok katlı Traianus Pazarı, tonozlu caddeleri ve dükkanlarıyla (tabernae) Roma sivil ve ticari tuğla-beton mimarisinin en ileri örneğidir.'),
  ('Erken Hristiyanlıkta İmparator Konstantin\'in annesi Azize Helena\'nın kutsal topraklarda İsa\'nın doğduğu mağara ve dirildiği mezar üzerinde 4. yüzyılda inşa edilmesine öncülük ettiği iki anıtsal kilise hangileridir?', 'Beytlehem Doğuş Kilisesi ve Kudüs Kutsal Kabir (Kıyame) Kilisesi', ['Ravenna San Vitale ve Venedik San Marco Kilisesi', 'Roma Santa Sabina ve Milano Sant\'Ambrogio Kilisesi', 'İskenderiye Serapeum ve Efes Meryem Ana Kilisesi'], 'Konstantin ve annesi Helena\'nın baniliğinde kutsal mekanları anıtlaştırmak (martyrium) amacıyla Beytlehem\'deki sekizgen doğuş alanı bazilikası ve Kudüs\'teki Kutsal Kabir Rotondası (Anastasis) inşa edilmiştir.'),
];
